-- Kiem tra ket qua
SELECT t.TopicId, t.Title AS ChuDe, q.Level AS MucDo, SUM(CASE WHEN q.QuestionType='mcq' THEN 1 ELSE 0 END) AS TracNghiem, SUM(CASE WHEN q.QuestionType='essay' THEN 1 ELSE 0 END) AS TuLuan, COUNT(*) AS Tong FROM Questions q JOIN Topics t ON t.TopicId=q.TopicId WHERE q.IsActive=1 GROUP BY t.TopicId, t.Title, q.Level ORDER BY t.TopicId, q.Level;
SELECT COUNT(*) AS TongCauHoi FROM Questions WHERE IsActive=1;
