INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cặp số nào sau đây là nghiệm của phương trình $3x + 2y = 2$?', 1, N'Thay $x = 4,\ y = -5$: $3\cdot 4 + 2\cdot (-5) = 2$ (đúng).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(4; -5)$', 1), (@q, 'B', N'$(4; -6)$', 0), (@q, 'C', N'$(3; -5)$', 0), (@q, 'D', N'$(-5; 4)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Phương trình nào sau đây là phương trình bậc nhất hai ẩn?', 1, N'Phương trình bậc nhất hai ẩn có dạng $ax + by = c$ với $a, b$ không đồng thời bằng $0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$5xy - 4x = 1$', 0), (@q, 'B', N'$0x + 0y = 1$', 0), (@q, 'C', N'$\frac{5}{x} + 2y = 1$', 0), (@q, 'D', N'$-4x + 2y = -3$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cho phương trình $x - y = -3$. Với $x = -5$ thì giá trị tương ứng của $y$ là:', 1, N'Thay $x = -5$: $-y = -3 - (-5) = 2 \Rightarrow y = -2$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-1$', 0), (@q, 'B', N'$-2$', 1), (@q, 'C', N'$-3$', 0), (@q, 'D', N'$2$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Trong phương trình $-3x + 6y = -8$, hệ số của ẩn $y$ là:', 1, N'Phương trình có dạng $ax + by = c$ với $a = -3,\ b = 6,\ c = -8$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$6$', 1), (@q, 'B', N'$-8$', 0), (@q, 'C', N'$-6$', 0), (@q, 'D', N'$-3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cặp số nào sau đây là nghiệm của phương trình $6x + 5y = -9$?', 1, N'Thay $x = 1,\ y = -3$: $6\cdot 1 + 5\cdot (-3) = -9$ (đúng).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(0; -3)$', 0), (@q, 'B', N'$(2; -2)$', 0), (@q, 'C', N'$(2; -3)$', 0), (@q, 'D', N'$(1; -3)$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Phương trình nào sau đây là phương trình bậc nhất hai ẩn?', 1, N'Phương trình bậc nhất hai ẩn có dạng $ax + by = c$ với $a, b$ không đồng thời bằng $0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-3x + 2y^2 = 2$', 0), (@q, 'B', N'$2xy - 3x = 4$', 0), (@q, 'C', N'$\frac{2}{x} + 4y = 4$', 0), (@q, 'D', N'$-3x + 4y = 2$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cho phương trình $x + y = 10$. Với $x = 2$ thì giá trị tương ứng của $y$ là:', 1, N'Thay $x = 2$: $y = 10 - 2 = 8 \Rightarrow y = 8$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$9$', 0), (@q, 'B', N'$-8$', 0), (@q, 'C', N'$8$', 1), (@q, 'D', N'$7$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Trong phương trình $-8x - 9y = -4$, hệ số của ẩn $y$ là:', 1, N'Phương trình có dạng $ax + by = c$ với $a = -8,\ b = -9,\ c = -4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-4$', 0), (@q, 'B', N'$9$', 0), (@q, 'C', N'$-9$', 1), (@q, 'D', N'$-8$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cặp số nào sau đây là nghiệm của phương trình $-5x - 2y = -7$?', 1, N'Thay $x = 1,\ y = 1$: $-5\cdot 1 + (-2)\cdot 1 = -7$ (đúng).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-1; -1)$', 0), (@q, 'B', N'$(2; 1)$', 0), (@q, 'C', N'$(1; 1)$', 1), (@q, 'D', N'$(1; 2)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cho phương trình $x - y = 3$. Với $x = -4$ thì giá trị tương ứng của $y$ là:', 1, N'Thay $x = -4$: $-y = 3 - (-4) = 7 \Rightarrow y = -7$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$7$', 0), (@q, 'B', N'$-7$', 1), (@q, 'C', N'$-6$', 0), (@q, 'D', N'$-8$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Trong phương trình $-x + 6y = 8$, hệ số của ẩn $y$ là:', 1, N'Phương trình có dạng $ax + by = c$ với $a = -1,\ b = 6,\ c = 8$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-1$', 0), (@q, 'B', N'$6$', 1), (@q, 'C', N'$-6$', 0), (@q, 'D', N'$8$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Cặp số nào sau đây là nghiệm của phương trình $6x + 4y = 6$?', 1, N'Thay $x = 1,\ y = 0$: $6\cdot 1 + 4\cdot 0 = 6$ (đúng).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(1; 0)$', 1), (@q, 'B', N'$(2; 1)$', 0), (@q, 'C', N'$(0; 1)$', 0), (@q, 'D', N'$(0; 0)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Cặp số $(-2; 0)$ có phải là nghiệm của phương trình $5x + y = -9$ không? Vì sao?', 1, N'Thay $x = -2,\ y = 0$ vào vế trái: $5\cdot (-2) + 1\cdot 0 = -10$.<br>Vì $-10 \ne -9$ nên $(-2; 0)$ <b>không phải</b> là nghiệm của phương trình.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Cặp số $(-1; 4)$ có phải là nghiệm của phương trình $x + 3y = 11$ không? Vì sao?', 1, N'Thay $x = -1,\ y = 4$ vào vế trái: $1\cdot (-1) + 3\cdot 4 = 11$.<br>Vì $11 = 11$ nên $(-1; 4)$ <b>là</b> nghiệm của phương trình.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Cặp số $(0; -4)$ có phải là nghiệm của phương trình $3x + 5y = -22$ không? Vì sao?', 1, N'Thay $x = 0,\ y = -4$ vào vế trái: $3\cdot 0 + 5\cdot (-4) = -20$.<br>Vì $-20 \ne -22$ nên $(0; -4)$ <b>không phải</b> là nghiệm của phương trình.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Tìm $m$ để cặp số $(-3; 1)$ là nghiệm của phương trình $mx - 3y = -15$.', 2, N'Thay $x = -3,\ y = 1$: $-3m - 3 = -15 \Rightarrow m = 4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = -4$', 0), (@q, 'B', N'$m = 3$', 0), (@q, 'C', N'$m = 5$', 0), (@q, 'D', N'$m = 4$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Nghiệm tổng quát của phương trình $x + y = -2$ là:', 2, N'Từ phương trình suy ra $y = -x - 2$ với $x$ tùy ý.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x \in \mathbb{R},\ y = x - 2$', 0), (@q, 'B', N'$x \in \mathbb{R},\ y = -x + 2$', 0), (@q, 'C', N'$x \in \mathbb{R},\ y = x + 2$', 0), (@q, 'D', N'$x \in \mathbb{R},\ y = -x - 2$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Đường thẳng $6x + y = 24$ cắt trục $Ox$ tại điểm:', 2, N'Giao với trục $Ox$ thì $y = 0$: $6x = 24 \Rightarrow x = 4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-4; 0)$', 0), (@q, 'B', N'$(0; 4)$', 0), (@q, 'C', N'$(24; 0)$', 0), (@q, 'D', N'$(4; 0)$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Tìm $m$ để cặp số $(2; 2)$ là nghiệm của phương trình $mx + 5y = -2$.', 2, N'Thay $x = 2,\ y = 2$: $2m + 10 = -2 \Rightarrow m = -6$.', 'manual', @admin);
