INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Nghiệm tổng quát của phương trình $-6x + y = -4$ là:', 2, N'Từ phương trình suy ra $y = 6x - 4$ với $x$ tùy ý.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x \in \mathbb{R},\ y = -6x + 4$', 0), (@q, 'B', N'$x \in \mathbb{R},\ y = 6x + 4$', 0), (@q, 'C', N'$x \in \mathbb{R},\ y = -6x - 4$', 0), (@q, 'D', N'$x \in \mathbb{R},\ y = 6x - 4$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Đường thẳng $5x + 6y = -18$ cắt trục $Oy$ tại điểm:', 2, N'Giao với trục $Oy$ thì $x = 0$: $6y = -18 \Rightarrow y = -3$.', 'manual', @admin);
