INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Tìm $m$ để cặp số $(-1; 2)$ là nghiệm của phương trình $mx - y = -8$.', 2, N'Thay $x = -1,\ y = 2$: $-m - 2 = -8 \Rightarrow m = 6$.', 'manual', @admin);
