INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Tìm $m$ để cặp số $(-3; 0)$ là nghiệm của phương trình $mx + y = 12$.', 2, N'Thay $x = -3,\ y = 0$: $-3m = 12 \Rightarrow m = -4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = -5$', 0), (@q, 'B', N'$m = -4$', 1), (@q, 'C', N'$m = -3$', 0), (@q, 'D', N'$m = 4$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Viết công thức nghiệm tổng quát của phương trình $2x + y = -7$ và chỉ ra ba nghiệm cụ thể của phương trình.', 2, N'Ta có $y = -2x - 7$. Nghiệm tổng quát: $x \in \mathbb{R},\ y = -2x - 7$.<br>Ví dụ (lần lượt chọn $x = -3, -1, 0$): $(-3; -1), (-1; -5), (0; -7)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm $m$ để điểm $M(-1; -2)$ thuộc đường thẳng $-4x + my = -6$.', 2, N'$M$ thuộc đường thẳng khi $-4\cdot (-1) + m\cdot (-2) = -6$<br>$\Leftrightarrow -2m = -10 \Leftrightarrow m = 5$. Vậy $m = 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Viết công thức nghiệm tổng quát của phương trình $-x + y = -3$ và chỉ ra ba nghiệm cụ thể của phương trình.', 2, N'Ta có $y = x - 3$. Nghiệm tổng quát: $x \in \mathbb{R},\ y = x - 3$.<br>Ví dụ (lần lượt chọn $x = 0, 1, 3$): $(0; -3), (1; -2), (3; 0)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm $m$ để điểm $M(4; 3)$ thuộc đường thẳng $-3x + my = 3$.', 2, N'$M$ thuộc đường thẳng khi $-3\cdot 4 + m\cdot 3 = 3$<br>$\Leftrightarrow 3m = 15 \Leftrightarrow m = 5$. Vậy $m = 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Viết công thức nghiệm tổng quát của phương trình $2x + y = -8$ và chỉ ra ba nghiệm cụ thể của phương trình.', 2, N'Ta có $y = -2x - 8$. Nghiệm tổng quát: $x \in \mathbb{R},\ y = -2x - 8$.<br>Ví dụ (lần lượt chọn $x = -3, -1, 2$): $(-3; -2), (-1; -6), (2; -12)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Bạn An mua $x$ quyển vở, mỗi quyển giá $9$ nghìn đồng và $y$ cây bút, mỗi cây giá $4$ nghìn đồng, hết tất cả $99$ nghìn đồng. Phương trình biểu thị mối liên hệ giữa $x$ và $y$ là:', 3, N'Tiền vở là $9x$, tiền bút là $4y$ (nghìn đồng) nên $9x + 4y = 99$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$9x - 4y = 99$', 0), (@q, 'B', N'$9x + 4y = 99$', 1), (@q, 'C', N'$x + y = 99$', 0), (@q, 'D', N'$4x + 9y = 99$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Số nghiệm nguyên dương $(x; y)$ của phương trình $7x + 5y = 40$ là:', 3, N'Thử $x = 1, 2, \dots$ sao cho $40 - 7x$ dương và chia hết cho $5$, được: $(5; 1)$. Vậy có $1$ nghiệm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$0$', 0), (@q, 'B', N'$1$', 1), (@q, 'C', N'$2$', 0), (@q, 'D', N'$3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Bạn An mua $x$ quyển vở, mỗi quyển giá $8$ nghìn đồng và $y$ cây bút, mỗi cây giá $15$ nghìn đồng, hết tất cả $184$ nghìn đồng. Phương trình biểu thị mối liên hệ giữa $x$ và $y$ là:', 3, N'Tiền vở là $8x$, tiền bút là $15y$ (nghìn đồng) nên $8x + 15y = 184$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x + y = 184$', 0), (@q, 'B', N'$8x - 15y = 184$', 0), (@q, 'C', N'$15x + 8y = 184$', 0), (@q, 'D', N'$8x + 15y = 184$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Số nghiệm nguyên dương $(x; y)$ của phương trình $7x + 3y = 30$ là:', 3, N'Thử $x = 1, 2, \dots$ sao cho $30 - 7x$ dương và chia hết cho $3$, được: $(3; 3)$. Vậy có $1$ nghiệm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$3$', 0), (@q, 'B', N'$0$', 0), (@q, 'C', N'$2$', 0), (@q, 'D', N'$1$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Bạn An mua $x$ quyển vở, mỗi quyển giá $9$ nghìn đồng và $y$ cây bút, mỗi cây giá $4$ nghìn đồng, hết tất cả $57$ nghìn đồng. Phương trình biểu thị mối liên hệ giữa $x$ và $y$ là:', 3, N'Tiền vở là $9x$, tiền bút là $4y$ (nghìn đồng) nên $9x + 4y = 57$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$9x + 4y = 57$', 1), (@q, 'B', N'$x + y = 57$', 0), (@q, 'C', N'$4x + 9y = 57$', 0), (@q, 'D', N'$9x - 4y = 57$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Số nghiệm nguyên dương $(x; y)$ của phương trình $7x + 2y = 25$ là:', 3, N'Thử $x = 1, 2, \dots$ sao cho $25 - 7x$ dương và chia hết cho $2$, được: $(1; 9)$, $(3; 2)$. Vậy có $2$ nghiệm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$4$', 0), (@q, 'B', N'$1$', 0), (@q, 'C', N'$2$', 1), (@q, 'D', N'$3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm tất cả các nghiệm nguyên dương của phương trình $2x + 7y = 21$.', 3, N'Vì $y \ge 1$ nên $2x \le 14 \Rightarrow x \le 7$. Ta cần $21 - 2x$ chia hết cho $7$ và dương.<br>Thử lần lượt các giá trị của $x$, được các nghiệm: $(7; 1)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Một cửa hàng bán bút giá $6$ nghìn đồng/cây và vở giá $10$ nghìn đồng/quyển. Lan có đúng $60$ nghìn đồng và muốn mua cả hai loại (mỗi loại ít nhất 1) sao cho tiêu hết số tiền. Hỏi Lan có thể mua bao nhiêu bút, bao nhiêu vở?', 3, N'Gọi $x$ là số bút, $y$ là số vở ($x, y$ nguyên dương). Ta có $6x + 10y = 60$.<br>Thử các giá trị $x$ từ $1$ đến $8$, được các cách mua: $5$ bút và $3$ vở.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm điểm thuộc đường thẳng $x + 6y = 10$ có tọa độ thỏa mãn $x = -y$.', 3, N'Thay $y = -x$ vào phương trình: $x + 6\cdot (-x) = 10 \Leftrightarrow -5x = 10$<br>$\Rightarrow x = -2,\ y = 2$. Điểm cần tìm là $(-2; 2)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm tất cả các nghiệm nguyên dương của phương trình $6x + 5y = 45$.', 3, N'Vì $y \ge 1$ nên $6x \le 40 \Rightarrow x \le 6$. Ta cần $45 - 6x$ chia hết cho $5$ và dương.<br>Thử lần lượt các giá trị của $x$, được các nghiệm: $(5; 3)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Một cửa hàng bán bút giá $15$ nghìn đồng/cây và vở giá $4$ nghìn đồng/quyển. Lan có đúng $67$ nghìn đồng và muốn mua cả hai loại (mỗi loại ít nhất 1) sao cho tiêu hết số tiền. Hỏi Lan có thể mua bao nhiêu bút, bao nhiêu vở?', 3, N'Gọi $x$ là số bút, $y$ là số vở ($x, y$ nguyên dương). Ta có $15x + 4y = 67$.<br>Thử các giá trị $x$ từ $1$ đến $4$, được các cách mua: $1$ bút và $13$ vở.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm điểm thuộc đường thẳng $2x - 3y = -8$ có tọa độ thỏa mãn $y = 2x$.', 3, N'Thay $y = 2x$ vào phương trình: $2x + (-3)\cdot (2x) = -8 \Leftrightarrow -4x = -8$<br>$\Rightarrow x = 2,\ y = 4$. Điểm cần tìm là $(2; 4)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm tất cả các nghiệm nguyên dương của phương trình $7x + 5y = 46$.', 3, N'Vì $y \ge 1$ nên $7x \le 41 \Rightarrow x \le 5$. Ta cần $46 - 7x$ chia hết cho $5$ và dương.<br>Thử lần lượt các giá trị của $x$, được các nghiệm: $(3; 5)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Một cửa hàng bán bút giá $6$ nghìn đồng/cây và vở giá $10$ nghìn đồng/quyển. Lan có đúng $54$ nghìn đồng và muốn mua cả hai loại (mỗi loại ít nhất 1) sao cho tiêu hết số tiền. Hỏi Lan có thể mua bao nhiêu bút, bao nhiêu vở?', 3, N'Gọi $x$ là số bút, $y$ là số vở ($x, y$ nguyên dương). Ta có $6x + 10y = 54$.<br>Thử các giá trị $x$ từ $1$ đến $7$, được các cách mua: $4$ bút và $3$ vở.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm điểm thuộc đường thẳng $-2x + 5y = -9$ có tọa độ thỏa mãn $x = y$.', 3, N'Thay $y = x$ vào phương trình: $-2x + 5\cdot (x) = -9 \Leftrightarrow 3x = -9$<br>$\Rightarrow x = -3,\ y = -3$. Điểm cần tìm là $(-3; -3)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'mcq', N'Phương trình $7x + 3y = 63$ có bao nhiêu nghiệm $(x; y)$ với $x, y$ là các số nguyên dương?', 4, N'Các nghiệm nguyên dương: $(3; 14)$, $(6; 7)$. Có $2$ nghiệm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$1$', 0), (@q, 'B', N'$3$', 0), (@q, 'C', N'$4$', 0), (@q, 'D', N'$2$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm nghiệm nguyên dương $(x; y)$ của phương trình $8x + 5y = 93$ sao cho $x + y$ nhỏ nhất.', 4, N'Liệt kê các nghiệm nguyên dương: $(1; 17)$ ($x + y = 18$), $(6; 9)$ ($x + y = 15$), $(11; 1)$ ($x + y = 12$).<br>Vậy nghiệm cần tìm là $(11; 1)$, khi đó $x + y = 12$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm $m$ để ba đường thẳng $d_1: 2x - y = -8$, $d_2: -3x - y = 7$ và $d_3: mx + y = -10$ cùng đi qua một điểm.', 4, N'Giải hệ gồm $d_1, d_2$ được giao điểm $I(-3; 2)$ (kiểm tra: $2\cdot(-3) + (-1)\cdot2 = -8$; $-3\cdot(-3) + (-1)\cdot2 = 7$).<br>$d_3$ đi qua $I$ khi $-3m + 2 = -10 \Leftrightarrow m = 4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm nghiệm nguyên dương $(x; y)$ của phương trình $5x + 4y = 111$ sao cho $x + y$ nhỏ nhất.', 4, N'Liệt kê các nghiệm nguyên dương: $(3; 24)$ ($x + y = 27$), $(7; 19)$ ($x + y = 26$), $(11; 14)$ ($x + y = 25$), $(15; 9)$ ($x + y = 24$), $(19; 4)$ ($x + y = 23$).<br>Vậy nghiệm cần tìm là $(19; 4)$, khi đó $x + y = 23$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(1, 'essay', N'Tìm $m$ để ba đường thẳng $d_1: 4x + y = 6$, $d_2: -3x + 4y = -14$ và $d_3: mx + y = -10$ cùng đi qua một điểm.', 4, N'Giải hệ gồm $d_1, d_2$ được giao điểm $I(2; -2)$ (kiểm tra: $4\cdot2 + 1\cdot(-2) = 6$; $-3\cdot2 + 4\cdot(-2) = -14$).<br>$d_3$ đi qua $I$ khi $2m - 2 = -10 \Leftrightarrow m = -4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} 4x - 5y = -21 \\ x - 2y = -9 \end{cases}$?', 1, N'Thay $(1; 5)$ vào cả hai phương trình đều thỏa mãn: $4\cdot1 + (-5)\cdot5 = -21$ và $1\cdot1 + (-2)\cdot5 = -9$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(5; 1)$', 0), (@q, 'B', N'$(-1; -5)$', 0), (@q, 'C', N'$(1; 5)$', 1), (@q, 'D', N'$(2; 5)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình nào sau đây là hệ hai phương trình bậc nhất hai ẩn?', 1, N'Mỗi phương trình của hệ phải có dạng $ax + by = c$ với $a, b$ không đồng thời bằng $0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\begin{cases} 4x^2 - 3y = 1 \\ x + 3y = -5 \end{cases}$', 0), (@q, 'B', N'$\begin{cases} 4x - 3y = 1 \\ x + 3y = -5 \end{cases}$', 1), (@q, 'C', N'$\begin{cases} 4x - 3y = 1 \\ x + \frac{3}{y} = -5 \end{cases}$', 0), (@q, 'D', N'$\begin{cases} 4xy - 3y = 1 \\ x + 3y = -5 \end{cases}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình $\begin{cases} -3x - 2y = -3 \\ 2x + 4y = 9 \end{cases}$', 1, N'Vì $\frac{-3}{2} \ne \frac{-2}{4}$ nên hai đường thẳng cắt nhau.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Có đúng hai nghiệm', 0), (@q, 'B', N'Có nghiệm duy nhất', 1), (@q, 'C', N'Vô số nghiệm', 0), (@q, 'D', N'Vô nghiệm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} -3x + 3y = -6 \\ 2x + y = 13 \end{cases}$?', 1, N'Thay $(5; 3)$ vào cả hai phương trình đều thỏa mãn: $-3\cdot5 + 3\cdot3 = -6$ và $2\cdot5 + 1\cdot3 = 13$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(3; 5)$', 0), (@q, 'B', N'$(6; 3)$', 0), (@q, 'C', N'$(-5; -3)$', 0), (@q, 'D', N'$(5; 3)$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình nào sau đây là hệ hai phương trình bậc nhất hai ẩn?', 1, N'Mỗi phương trình của hệ phải có dạng $ax + by = c$ với $a, b$ không đồng thời bằng $0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\begin{cases} 4xy + 3y = 3 \\ -2x + 5y = 3 \end{cases}$', 0), (@q, 'B', N'$\begin{cases} 4x + 3y = 3 \\ -2x + 5y = 3 \end{cases}$', 1), (@q, 'C', N'$\begin{cases} 4x + 3y = 3 \\ -2x + \frac{5}{y} = 3 \end{cases}$', 0), (@q, 'D', N'$\begin{cases} 4x^2 + 3y = 3 \\ -2x + 5y = 3 \end{cases}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình $\begin{cases} -5x + 4y = 5 \\ x - 4y = -2 \end{cases}$', 1, N'Vì $\frac{-5}{1} \ne \frac{4}{-4}$ nên hai đường thẳng cắt nhau.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Có nghiệm duy nhất', 1), (@q, 'B', N'Vô số nghiệm', 0), (@q, 'C', N'Vô nghiệm', 0), (@q, 'D', N'Có đúng hai nghiệm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} -x + 4y = 13 \\ x + 4y = 3 \end{cases}$?', 1, N'Thay $(-5; 2)$ vào cả hai phương trình đều thỏa mãn: $-1\cdot(-5) + 4\cdot2 = 13$ và $1\cdot(-5) + 4\cdot2 = 3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-4; 2)$', 0), (@q, 'B', N'$(5; -2)$', 0), (@q, 'C', N'$(-5; 2)$', 1), (@q, 'D', N'$(2; -5)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} -x + 2y = -4 \\ -3x - 2y = -12 \end{cases}$?', 1, N'Thay $(4; 0)$ vào cả hai phương trình đều thỏa mãn: $-1\cdot4 + 2\cdot0 = -4$ và $-3\cdot4 + (-2)\cdot0 = -12$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-4; 0)$', 0), (@q, 'B', N'$(4; 0)$', 1), (@q, 'C', N'$(0; 4)$', 0), (@q, 'D', N'$(5; 0)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình $\begin{cases} -4x + 4y = 6 \\ -8x + 8y = 13 \end{cases}$', 1, N'Hệ số của $x, y$ ở phương trình thứ hai gấp $2$ lần phương trình thứ nhất nhưng hệ số tự do thì không, nên hai đường thẳng song song.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Có nghiệm duy nhất', 0), (@q, 'B', N'Vô số nghiệm', 0), (@q, 'C', N'Vô nghiệm', 1), (@q, 'D', N'Có đúng hai nghiệm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} -5x - 2y = 28 \\ 2x - y = -4 \end{cases}$?', 1, N'Thay $(-4; -4)$ vào cả hai phương trình đều thỏa mãn: $-5\cdot(-4) + (-2)\cdot(-4) = 28$ và $2\cdot(-4) + (-1)\cdot(-4) = -4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-4; -4)$', 1), (@q, 'B', N'$(4; 4)$', 0), (@q, 'C', N'$(-4; -5)$', 0), (@q, 'D', N'$(-3; -4)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Hệ phương trình $\begin{cases} -4x + 4y = -6 \\ -8x + 8y = -13 \end{cases}$', 1, N'Hệ số của $x, y$ ở phương trình thứ hai gấp $2$ lần phương trình thứ nhất nhưng hệ số tự do thì không, nên hai đường thẳng song song.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Vô nghiệm', 1), (@q, 'B', N'Có đúng hai nghiệm', 0), (@q, 'C', N'Vô số nghiệm', 0), (@q, 'D', N'Có nghiệm duy nhất', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Cặp số nào sau đây là nghiệm của hệ phương trình $\begin{cases} -x + 3y = -8 \\ -4x - 4y = 0 \end{cases}$?', 1, N'Thay $(2; -2)$ vào cả hai phương trình đều thỏa mãn: $-1\cdot2 + 3\cdot(-2) = -8$ và $-4\cdot2 + (-4)\cdot(-2) = 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-2; 2)$', 0), (@q, 'B', N'$(3; -2)$', 0), (@q, 'C', N'$(2; -3)$', 0), (@q, 'D', N'$(2; -2)$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cặp số $(-3; 5)$ có là nghiệm của hệ phương trình $\begin{cases} -3x + 2y = 19 \\ -2x - 2y = -4 \end{cases}$ không?', 1, N'Thay $x = -3,\ y = 5$:<br>- Phương trình thứ nhất: $-3\cdot(-3) + 2\cdot5 = 19$ (thỏa mãn).<br>- Phương trình thứ hai: $-2\cdot(-3) + (-2)\cdot5 = -4$ (thỏa mãn).<br>Vậy cặp số <b>là</b> nghiệm của hệ.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cặp số $(-3; -1)$ có là nghiệm của hệ phương trình $\begin{cases} -5x + 3y = 12 \\ -3x + 5y = 4 \end{cases}$ không?', 1, N'Thay $x = -3,\ y = -1$:<br>- Phương trình thứ nhất: $-5\cdot(-3) + 3\cdot(-1) = 12$ (thỏa mãn).<br>- Phương trình thứ hai: $-3\cdot(-3) + 5\cdot(-1) = 4$ (thỏa mãn).<br>Vậy cặp số <b>là</b> nghiệm của hệ.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cặp số $(-2; -1)$ có là nghiệm của hệ phương trình $\begin{cases} 4x - y = -3 \\ 3x - 5y = 2 \end{cases}$ không?', 1, N'Thay $x = -2,\ y = -1$:<br>- Phương trình thứ nhất: $4\cdot(-2) + (-1)\cdot(-1) = -7$ $\ne -3$ (không thỏa mãn).<br>- Phương trình thứ hai: $3\cdot(-2) + (-5)\cdot(-1) = -1$ $\ne 2$ (không thỏa mãn).<br>Vậy cặp số <b>không phải</b> là nghiệm của hệ.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Nghiệm của hệ phương trình $\begin{cases} x - y = -2 \\ 5x + 3y = 6 \end{cases}$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $3$, phương trình thứ hai với $(-1)$ rồi trừ vế theo vế: $8x = 0 \Rightarrow x = 0$.<br>Thay vào phương trình thứ nhất: $-y = -2 - 0 \Rightarrow y = 2$.<br>Vậy hệ có nghiệm duy nhất $(0; 2)$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(0; 2)$', 1), (@q, 'B', N'$(0; -2)$', 0), (@q, 'C', N'$(1; 1)$', 0), (@q, 'D', N'$(2; 0)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Biết $(x; y)$ là nghiệm của hệ $\begin{cases} 3x - 2y = -15 \\ 3x - y = -12 \end{cases}$. Giá trị của $x - y$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $(-1)$, phương trình thứ hai với $(-2)$ rồi trừ vế theo vế: $3x = -9 \Rightarrow x = -3$.<br>Thay vào phương trình thứ nhất: $-2y = -15 - (-9) \Rightarrow y = 3$.<br>Vậy hệ có nghiệm duy nhất $(-3; 3)$. Do đó $x - y = -6$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-6$', 1), (@q, 'B', N'$6$', 0), (@q, 'C', N'$-8$', 0), (@q, 'D', N'$-5$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Nghiệm của hệ phương trình $\begin{cases} -x + 4y = -9 \\ 4x + 2y = 0 \end{cases}$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $2$, phương trình thứ hai với $4$ rồi trừ vế theo vế: $-18x = -18 \Rightarrow x = 1$.<br>Thay vào phương trình thứ nhất: $4y = -9 - (-1) \Rightarrow y = -2$.<br>Vậy hệ có nghiệm duy nhất $(1; -2)$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(1; -2)$', 1), (@q, 'B', N'$(-2; 1)$', 0), (@q, 'C', N'$(1; 2)$', 0), (@q, 'D', N'$(-1; -2)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Biết $(x; y)$ là nghiệm của hệ $\begin{cases} -4x + 3y = -1 \\ 2x + 5y = 7 \end{cases}$. Giá trị của $x - y$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $5$, phương trình thứ hai với $3$ rồi trừ vế theo vế: $-26x = -26 \Rightarrow x = 1$.<br>Thay vào phương trình thứ nhất: $3y = -1 - (-4) \Rightarrow y = 1$.<br>Vậy hệ có nghiệm duy nhất $(1; 1)$. Do đó $x - y = 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$1$', 0), (@q, 'B', N'$0$', 1), (@q, 'C', N'$2$', 0), (@q, 'D', N'$-2$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Nghiệm của hệ phương trình $\begin{cases} -5x - 2y = -19 \\ 3x - 2y = 21 \end{cases}$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $(-2)$, phương trình thứ hai với $(-2)$ rồi trừ vế theo vế: $16x = 80 \Rightarrow x = 5$.<br>Thay vào phương trình thứ nhất: $-2y = -19 - (-25) \Rightarrow y = -3$.<br>Vậy hệ có nghiệm duy nhất $(5; -3)$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(5; 3)$', 0), (@q, 'B', N'$(5; -3)$', 1), (@q, 'C', N'$(-3; 5)$', 0), (@q, 'D', N'$(-5; -3)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Biết $(x; y)$ là nghiệm của hệ $\begin{cases} -3x + y = -13 \\ -5x + 3y = -27 \end{cases}$. Giá trị của $xy$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $3$, phương trình thứ hai với $1$ rồi trừ vế theo vế: $-4x = -12 \Rightarrow x = 3$.<br>Thay vào phương trình thứ nhất: $y = -13 - (-9) \Rightarrow y = -4$.<br>Vậy hệ có nghiệm duy nhất $(3; -4)$. Do đó $xy = -12$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-12$', 1), (@q, 'B', N'$-11$', 0), (@q, 'C', N'$12$', 0), (@q, 'D', N'$-14$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Nghiệm của hệ phương trình $\begin{cases} x + y = -2 \\ -2x - y = 5 \end{cases}$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $(-1)$, phương trình thứ hai với $1$ rồi trừ vế theo vế: $x = -3 \Rightarrow x = -3$.<br>Thay vào phương trình thứ nhất: $y = -2 - (-3) \Rightarrow y = 1$.<br>Vậy hệ có nghiệm duy nhất $(-3; 1)$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-3; 1)$', 1), (@q, 'B', N'$(-3; -1)$', 0), (@q, 'C', N'$(1; -3)$', 0), (@q, 'D', N'$(3; 1)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Biết $(x; y)$ là nghiệm của hệ $\begin{cases} -3x - 3y = 9 \\ 3x - 3y = -21 \end{cases}$. Giá trị của $x + y$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $(-3)$, phương trình thứ hai với $(-3)$ rồi trừ vế theo vế: $18x = -90 \Rightarrow x = -5$.<br>Thay vào phương trình thứ nhất: $-3y = 9 - 15 \Rightarrow y = 2$.<br>Vậy hệ có nghiệm duy nhất $(-5; 2)$. Do đó $x + y = -3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-2$', 0), (@q, 'B', N'$-3$', 1), (@q, 'C', N'$-5$', 0), (@q, 'D', N'$3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Nghiệm của hệ phương trình $\begin{cases} x + 2y = -3 \\ 5x + 5y = 5 \end{cases}$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $5$, phương trình thứ hai với $2$ rồi trừ vế theo vế: $-5x = -25 \Rightarrow x = 5$.<br>Thay vào phương trình thứ nhất: $2y = -3 - 5 \Rightarrow y = -4$.<br>Vậy hệ có nghiệm duy nhất $(5; -4)$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$(-5; -4)$', 0), (@q, 'B', N'$(5; 4)$', 0), (@q, 'C', N'$(5; -4)$', 1), (@q, 'D', N'$(-4; 5)$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Biết $(x; y)$ là nghiệm của hệ $\begin{cases} -5x + y = -15 \\ -2x + 3y = -19 \end{cases}$. Giá trị của $x + y$ là:', 2, N'Nhân hai vế phương trình thứ nhất với $3$, phương trình thứ hai với $1$ rồi trừ vế theo vế: $-13x = -26 \Rightarrow x = 2$.<br>Thay vào phương trình thứ nhất: $y = -15 - (-10) \Rightarrow y = -5$.<br>Vậy hệ có nghiệm duy nhất $(2; -5)$. Do đó $x + y = -3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-3$', 1), (@q, 'B', N'$-2$', 0), (@q, 'C', N'$3$', 0), (@q, 'D', N'$-5$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Giải hệ phương trình $\begin{cases} 2x + 5y = -7 \\ 5x + 5y = 5 \end{cases}$.', 2, N'Nhân hai vế phương trình thứ nhất với $5$, phương trình thứ hai với $5$ rồi trừ vế theo vế: $-15x = -60 \Rightarrow x = 4$.<br>Thay vào phương trình thứ nhất: $5y = -7 - 8 \Rightarrow y = -3$.<br>Vậy hệ có nghiệm duy nhất $(4; -3)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Giải hệ phương trình $\begin{cases} -4x + y = -3 \\ 3x + 2y = -6 \end{cases}$ bằng phương pháp thế.', 2, N'Từ phương trình thứ nhất: $y = 4x - 3$.<br>Thế vào phương trình thứ hai: $3x + 2\left(4x - 3\right) = -6$ $\Leftrightarrow 11x = 0 \Leftrightarrow x = 0$.<br>Suy ra $y = -3$. Vậy hệ có nghiệm duy nhất $(0; -3)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Giải hệ phương trình $\begin{cases} 2x + y = -11 \\ -x + 2y = -7 \end{cases}$.', 2, N'Nhân hai vế phương trình thứ nhất với $2$, phương trình thứ hai với $1$ rồi trừ vế theo vế: $5x = -15 \Rightarrow x = -3$.<br>Thay vào phương trình thứ nhất: $y = -11 - (-6) \Rightarrow y = -5$.<br>Vậy hệ có nghiệm duy nhất $(-3; -5)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Giải hệ phương trình $\begin{cases} 2x + y = -9 \\ 4x - 4y = -12 \end{cases}$ bằng phương pháp thế.', 2, N'Từ phương trình thứ nhất: $y = -2x - 9$.<br>Thế vào phương trình thứ hai: $4x + (-4)\left(-2x - 9\right) = -12$ $\Leftrightarrow 12x = -48 \Leftrightarrow x = -4$.<br>Suy ra $y = -1$. Vậy hệ có nghiệm duy nhất $(-4; -1)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Giải hệ phương trình $\begin{cases} -4x + 3y = -5 \\ -2x + 4y = -10 \end{cases}$.', 2, N'Nhân hai vế phương trình thứ nhất với $4$, phương trình thứ hai với $3$ rồi trừ vế theo vế: $-10x = 10 \Rightarrow x = -1$.<br>Thay vào phương trình thứ nhất: $3y = -5 - 4 \Rightarrow y = -3$.<br>Vậy hệ có nghiệm duy nhất $(-1; -3)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Một rạp chiếu phim bán vé người lớn giá $60$ nghìn đồng và vé trẻ em giá $40$ nghìn đồng. Một buổi bán được $44$ vé, thu về $2160$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 44 \\ 60x + 40y = 2160 \end{cases}$.<br>Thế $y = 44 - x$: $(60 - 40)x = 2160 - 40\cdot 44 = 400 \Rightarrow x = 20,\ y = 24$.<br>Vậy bán $20$ vé người lớn và $24$ vé trẻ em.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'18 vé người lớn, 26 vé trẻ em', 0), (@q, 'B', N'21 vé người lớn, 23 vé trẻ em', 0), (@q, 'C', N'24 vé người lớn, 20 vé trẻ em', 0), (@q, 'D', N'20 vé người lớn, 24 vé trẻ em', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Tìm $m$ để hệ phương trình $\begin{cases} mx + y = 0 \\ 2x - y = 6 \end{cases}$ có nghiệm $x = 1$.', 3, N'Với $x = 1$, từ phương trình thứ hai: $-y = 6 - 2 \Rightarrow y = -4$.<br>Thay vào phương trình thứ nhất: $m - 4 = 0 \Rightarrow m = 4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = -4$', 0), (@q, 'B', N'$m = 2$', 0), (@q, 'C', N'$m = 4$', 1), (@q, 'D', N'$m = 5$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Một rạp chiếu phim bán vé người lớn giá $45$ nghìn đồng và vé trẻ em giá $25$ nghìn đồng. Một buổi bán được $48$ vé, thu về $1880$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 48 \\ 45x + 25y = 1880 \end{cases}$.<br>Thế $y = 48 - x$: $(45 - 25)x = 1880 - 25\cdot 48 = 680 \Rightarrow x = 34,\ y = 14$.<br>Vậy bán $34$ vé người lớn và $14$ vé trẻ em.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'14 vé người lớn, 34 vé trẻ em', 0), (@q, 'B', N'32 vé người lớn, 16 vé trẻ em', 0), (@q, 'C', N'34 vé người lớn, 14 vé trẻ em', 1), (@q, 'D', N'35 vé người lớn, 13 vé trẻ em', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Tìm $m$ để hệ phương trình $\begin{cases} mx + y = 11 \\ x + 3y = -7 \end{cases}$ có nghiệm $x = -4$.', 3, N'Với $x = -4$, từ phương trình thứ hai: $3y = -7 - (-4) \Rightarrow y = -1$.<br>Thay vào phương trình thứ nhất: $-4m - 1 = 11 \Rightarrow m = -3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = -5$', 0), (@q, 'B', N'$m = -3$', 1), (@q, 'C', N'$m = -2$', 0), (@q, 'D', N'$m = 3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Vừa gà vừa chó có $26$ con, đếm được tất cả $78$ chân. Hỏi có bao nhiêu con gà, bao nhiêu con chó?', 3, N'Gọi số gà là $x$, số chó là $y$ ($x, y$ nguyên dương). Ta có hệ $\begin{cases} x + y = 26 \\ 2x + 4y = 78 \end{cases}$.<br>Từ đó $2y = 78 - 2\cdot 26 = 26 \Rightarrow y = 13,\ x = 13$. Vậy có $13$ con gà và $13$ con chó.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'14 gà, 12 chó', 0), (@q, 'B', N'13 gà, 13 chó', 1), (@q, 'C', N'15 gà, 11 chó', 0), (@q, 'D', N'11 gà, 15 chó', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Tìm $m$ để hệ phương trình $\begin{cases} mx + y = 3 \\ -2x - 3y = 5 \end{cases}$ có nghiệm $x = 2$.', 3, N'Với $x = 2$, từ phương trình thứ hai: $-3y = 5 - (-4) \Rightarrow y = -3$.<br>Thay vào phương trình thứ nhất: $2m - 3 = 3 \Rightarrow m = 3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = 4$', 0), (@q, 'B', N'$m = -3$', 0), (@q, 'C', N'$m = 3$', 1), (@q, 'D', N'$m = 1$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Tìm hai số tự nhiên, biết tổng của chúng bằng $41$ và số lớn hơn số nhỏ $31$ đơn vị.', 3, N'Gọi số lớn là $x$, số nhỏ là $y$. Ta có hệ $\begin{cases} x + y = 41 \\ x - y = 31 \end{cases}$.<br>Cộng vế theo vế: $2x = 72 \Rightarrow x = 36,\ y = 5$. Vậy hai số là $36$ và $5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Một rạp chiếu phim bán vé người lớn giá $80$ nghìn đồng và vé trẻ em giá $50$ nghìn đồng. Một buổi bán được $43$ vé, thu về $2720$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 43 \\ 80x + 50y = 2720 \end{cases}$.<br>Thế $y = 43 - x$: $(80 - 50)x = 2720 - 50\cdot 43 = 570 \Rightarrow x = 19,\ y = 24$.<br>Vậy bán $19$ vé người lớn và $24$ vé trẻ em.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Một rạp chiếu phim bán vé người lớn giá $50$ nghìn đồng và vé trẻ em giá $30$ nghìn đồng. Một buổi bán được $22$ vé, thu về $920$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 22 \\ 50x + 30y = 920 \end{cases}$.<br>Thế $y = 22 - x$: $(50 - 30)x = 920 - 30\cdot 22 = 260 \Rightarrow x = 13,\ y = 9$.<br>Vậy bán $13$ vé người lớn và $9$ vé trẻ em.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Một rạp chiếu phim bán vé người lớn giá $45$ nghìn đồng và vé trẻ em giá $25$ nghìn đồng. Một buổi bán được $48$ vé, thu về $1540$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 48 \\ 45x + 25y = 1540 \end{cases}$.<br>Thế $y = 48 - x$: $(45 - 25)x = 1540 - 25\cdot 48 = 340 \Rightarrow x = 17,\ y = 31$.<br>Vậy bán $17$ vé người lớn và $31$ vé trẻ em.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Tìm số tự nhiên có hai chữ số, biết tổng hai chữ số bằng $11$ và nếu đổi chỗ hai chữ số thì được số mới lớn hơn số ban đầu $63$ đơn vị.', 3, N'Gọi chữ số hàng chục là $a$, hàng đơn vị là $b$. Ta có $a + b = 11$ và $(10b + a) - (10a + b) = 63 \Leftrightarrow b - a = 7$.<br>Giải hệ được $a = 2,\ b = 9$. Số cần tìm là $29$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Một rạp chiếu phim bán vé người lớn giá $80$ nghìn đồng và vé trẻ em giá $50$ nghìn đồng. Một buổi bán được $24$ vé, thu về $1440$ nghìn đồng. Hỏi đã bán bao nhiêu vé mỗi loại?', 3, N'Gọi số vé người lớn là $x$, vé trẻ em là $y$. Ta có hệ $\begin{cases} x + y = 24 \\ 80x + 50y = 1440 \end{cases}$.<br>Thế $y = 24 - x$: $(80 - 50)x = 1440 - 50\cdot 24 = 240 \Rightarrow x = 8,\ y = 16$.<br>Vậy bán $8$ vé người lớn và $16$ vé trẻ em.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Tìm hai số tự nhiên, biết tổng của chúng bằng $113$ và số lớn hơn số nhỏ $49$ đơn vị.', 3, N'Gọi số lớn là $x$, số nhỏ là $y$. Ta có hệ $\begin{cases} x + y = 113 \\ x - y = 49 \end{cases}$.<br>Cộng vế theo vế: $2x = 162 \Rightarrow x = 81,\ y = 32$. Vậy hai số là $81$ và $32$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Vừa gà vừa chó có $19$ con, đếm được tất cả $60$ chân. Hỏi có bao nhiêu con gà, bao nhiêu con chó?', 3, N'Gọi số gà là $x$, số chó là $y$ ($x, y$ nguyên dương). Ta có hệ $\begin{cases} x + y = 19 \\ 2x + 4y = 60 \end{cases}$.<br>Từ đó $2y = 60 - 2\cdot 19 = 22 \Rightarrow y = 11,\ x = 8$. Vậy có $8$ con gà và $11$ con chó.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Vừa gà vừa chó có $23$ con, đếm được tất cả $80$ chân. Hỏi có bao nhiêu con gà, bao nhiêu con chó?', 3, N'Gọi số gà là $x$, số chó là $y$ ($x, y$ nguyên dương). Ta có hệ $\begin{cases} x + y = 23 \\ 2x + 4y = 80 \end{cases}$.<br>Từ đó $2y = 80 - 2\cdot 23 = 34 \Rightarrow y = 17,\ x = 6$. Vậy có $6$ con gà và $17$ con chó.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'mcq', N'Với giá trị nào của $m$ thì hệ phương trình $\begin{cases} mx + y = 2 \\ 4x + y = 0 \end{cases}$ vô nghiệm?', 4, N'Hai đường thẳng song song (hệ vô nghiệm) khi $\frac{m}{4} = \frac{1}{1} = 1$, tức $m = 4$.<br>Khi đó vế trái phương trình thứ nhất bằng $1$ lần vế trái phương trình thứ hai, nhưng $2 \ne 1\cdot 0 = 0$ nên hai đường thẳng không trùng nhau.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = 8$', 0), (@q, 'B', N'$m = 4$', 1), (@q, 'C', N'$m = -4$', 0), (@q, 'D', N'$m \ne 4$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cho hệ phương trình $\begin{cases} x + y = m - 1 \\ x - y = m - 5 \end{cases}$ ($m$ là tham số). Tìm $m$ để nghiệm $(x; y)$ của hệ thỏa mãn $x = -2y$.', 4, N'Cộng vế theo vế: $2x = 2m - 6 \Rightarrow x = m - 3$; trừ vế theo vế: $y = 2$.<br>Điều kiện $x = -2y$: $m - 3 = -2\left(2\right) \Leftrightarrow m = -1$.<br>Vậy $m = -1$ (khi đó $x = -4,\ y = 2$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cho hệ phương trình $\begin{cases} x + y = -3m + 6 \\ x - y = -m + 4 \end{cases}$. Tìm $m$ để hệ có nghiệm $(x; y)$ với $x \gt 0$ và $y \gt 0$.', 4, N'Giải hệ: $x = -2m + 5$, $y = -m + 1$.<br>$x \gt 0 \Leftrightarrow m \lt \frac{5}{2}$; $\ y \gt 0 \Leftrightarrow m \lt 1$.<br>Kết hợp: $m \lt 1$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cho hệ phương trình $\begin{cases} x + y = m \\ x - y = -m - 2 \end{cases}$ ($m$ là tham số). Tìm $m$ để nghiệm $(x; y)$ của hệ thỏa mãn $x = 2y$.', 4, N'Cộng vế theo vế: $2x = -2 \Rightarrow x = -1$; trừ vế theo vế: $y = m + 1$.<br>Điều kiện $x = 2y$: $-1 = 2\left(m + 1\right) \Leftrightarrow -2m = 3 \Leftrightarrow m = -\frac{3}{2}$.<br>Vậy $m = -\frac{3}{2}$ (khi đó $x = -1,\ y = -\frac{1}{2}$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(2, 'essay', N'Cho hệ phương trình $\begin{cases} x + y = -3m + 4 \\ x - y = m - 4 \end{cases}$. Tìm $m$ để hệ có nghiệm $(x; y)$ với $x \gt 0$ và $y \gt 0$.', 4, N'Giải hệ: $x = -m$, $y = -2m + 4$.<br>$x \gt 0 \Leftrightarrow m \lt 0$; $\ y \gt 0 \Leftrightarrow m \lt 2$.<br>Kết hợp: $m \lt 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Giá trị của $\sqrt{16}$ là:', 1, N'Căn bậc hai số học là số không âm. Vì $4 \ge 0$ và bình phương của $4$ bằng biểu thức dưới dấu căn nên $\sqrt{16} = 4$.', 'manual', @admin);
