INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Rút gọn biểu thức $A = -2\sqrt{6} + \sqrt{96} - \sqrt{54}$.', 2, N'Đưa thừa số ra ngoài dấu căn: $\sqrt{6} = \sqrt{6}$, $\sqrt{96} = 4\sqrt{6}$, $\sqrt{54} = 3\sqrt{6}$.<br>$A = -2\sqrt{6} + 4\sqrt{6} - 3\sqrt{6} = -\sqrt{6}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Trục căn thức ở mẫu và rút gọn: $\frac{40}{\sqrt{5}}$ và $\frac{8}{\sqrt{5} + 1}$.', 2, N'$\frac{40}{\sqrt{5}} = \frac{40\sqrt{5}}{5} = 8\sqrt{5}$.<br>$\frac{8}{\sqrt{5} + 1} = \frac{8(\sqrt{5} - 1)}{5 - 1} = 2(\sqrt{5} - 1)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Rút gọn biểu thức $A = -2\sqrt{150} - 3\sqrt{6} + 3\sqrt{54}$.', 2, N'Đưa thừa số ra ngoài dấu căn: $\sqrt{150} = 5\sqrt{6}$, $\sqrt{6} = \sqrt{6}$, $\sqrt{54} = 3\sqrt{6}$.<br>$A = -10\sqrt{6} - 3\sqrt{6} + 9\sqrt{6} = -4\sqrt{6}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Trục căn thức ở mẫu và rút gọn: $\frac{18}{\sqrt{6}}$ và $\frac{3}{\sqrt{6} + 1}$.', 2, N'$\frac{18}{\sqrt{6}} = \frac{18\sqrt{6}}{6} = 3\sqrt{6}$.<br>$\frac{3}{\sqrt{6} + 1} = \frac{3(\sqrt{6} - 1)}{6 - 1} = \frac{3}{5}(\sqrt{6} - 1)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Rút gọn biểu thức $A = 2\sqrt{32} + \sqrt{2} - 2\sqrt{50}$.', 2, N'Đưa thừa số ra ngoài dấu căn: $\sqrt{32} = 4\sqrt{2}$, $\sqrt{2} = \sqrt{2}$, $\sqrt{50} = 5\sqrt{2}$.<br>$A = 8\sqrt{2} + \sqrt{2} - 10\sqrt{2} = -\sqrt{2}$.', 'manual', @admin);
