INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Tập nghiệm của phương trình $\sqrt{\left(x + 3\right)^2} = 5$ là:', 3, N'$\sqrt{A^2} = |A|$ nên $|x + 3| = 5 \Leftrightarrow x = -8$ hoặc $x = 2$.', 'manual', @admin);
