INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Trục căn thức ở mẫu của $\frac{1}{\sqrt{11} - \sqrt{6}}$ ta được:', 3, N'Nhân cả tử và mẫu với $\sqrt{11} + \sqrt{6}$: mẫu bằng $11 - 6 = 5$.', 'manual', @admin);
