INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Nghiệm của phương trình $\sqrt{x - 7} = 9$ là:', 3, N'Điều kiện $x \ge 7$. Bình phương hai vế: $x - 7 = 81 \Leftrightarrow x = 88$ (thỏa mãn).', 'manual', @admin);
