INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Trục căn thức ở mẫu của $\frac{1}{\sqrt{5} - \sqrt{2}}$ ta được:', 3, N'Nhân cả tử và mẫu với $\sqrt{5} + \sqrt{2}$: mẫu bằng $5 - 2 = 3$.', 'manual', @admin);
