INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{3x - 5} = 4$.', 3, N'Điều kiện: $3x - 5 \ge 0$.<br>Bình phương hai vế: $3x - 5 = 16 \Leftrightarrow 3x = 21 \Leftrightarrow x = 7$ (thỏa mãn điều kiện).<br>Vậy $x = 7$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Cho biểu thức $A = \frac{x - 4}{\sqrt{x} + 2} - 2\sqrt{x}$ với $x \ge 0$.<br>a) Rút gọn $A$.<br>b) Tính giá trị của $A$ khi $x = 81$.', 3, N'a) $x - 4 = (\sqrt{x} - 2)(\sqrt{x} + 2)$ nên $\frac{x - 4}{\sqrt{x} + 2} = \sqrt{x} - 2$.<br>$A = \sqrt{x} - 2 - 2\sqrt{x} = -\sqrt{x} - 2$.<br>b) Với $x = 81$ thì $\sqrt{x} = 9$, $A = -9 - 2 = -11$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{x^2 + 2x + 1} = 6$.', 3, N'Ta có $x^2 + 2x + 1 = \left(x + 1\right)^2$ nên phương trình trở thành $|x + 1| = 6$.<br>$\Leftrightarrow x + 1 = 6$ hoặc $x + 1 = -6$ $\Leftrightarrow x = 5$ hoặc $x = -7$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{x - 8} = 1$.', 3, N'Điều kiện: $x - 8 \ge 0$.<br>Bình phương hai vế: $x - 8 = 1 \Leftrightarrow x = 9 \Leftrightarrow x = 9$ (thỏa mãn điều kiện).<br>Vậy $x = 9$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Cho biểu thức $A = \frac{x - 4}{\sqrt{x} + 2} + 2\sqrt{x}$ với $x \ge 0$.<br>a) Rút gọn $A$.<br>b) Tính giá trị của $A$ khi $x = 16$.', 3, N'a) $x - 4 = (\sqrt{x} - 2)(\sqrt{x} + 2)$ nên $\frac{x - 4}{\sqrt{x} + 2} = \sqrt{x} - 2$.<br>$A = \sqrt{x} - 2 + 2\sqrt{x} = 3\sqrt{x} - 2$.<br>b) Với $x = 16$ thì $\sqrt{x} = 4$, $A = 3\cdot 4 - 2 = 10$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{x^2 - 2x + 1} = 4$.', 3, N'Ta có $x^2 - 2x + 1 = \left(x - 1\right)^2$ nên phương trình trở thành $|x - 1| = 4$.<br>$\Leftrightarrow x - 1 = 4$ hoặc $x - 1 = -4$ $\Leftrightarrow x = 5$ hoặc $x = -3$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{x + 6} = 6$.', 3, N'Điều kiện: $x + 6 \ge 0$.<br>Bình phương hai vế: $x + 6 = 36 \Leftrightarrow x = 30 \Leftrightarrow x = 30$ (thỏa mãn điều kiện).<br>Vậy $x = 30$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Cho biểu thức $A = \frac{x - 25}{\sqrt{x} + 5} - 2\sqrt{x}$ với $x \ge 0$.<br>a) Rút gọn $A$.<br>b) Tính giá trị của $A$ khi $x = 64$.', 3, N'a) $x - 25 = (\sqrt{x} - 5)(\sqrt{x} + 5)$ nên $\frac{x - 25}{\sqrt{x} + 5} = \sqrt{x} - 5$.<br>$A = \sqrt{x} - 5 - 2\sqrt{x} = -\sqrt{x} - 5$.<br>b) Với $x = 64$ thì $\sqrt{x} = 8$, $A = -8 - 5 = -13$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Giải phương trình $\sqrt{x^2 - 4x + 4} = 6$.', 3, N'Ta có $x^2 - 4x + 4 = \left(x - 2\right)^2$ nên phương trình trở thành $|x - 2| = 6$.<br>$\Leftrightarrow x - 2 = 6$ hoặc $x - 2 = -6$ $\Leftrightarrow x = 8$ hoặc $x = -4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'mcq', N'Giá trị nhỏ nhất của biểu thức $P = x - 8\sqrt{x} + 19$ (với $x \ge 0$) là:', 4, N'$P = (\sqrt{x} - 4)^2 + 3 \ge 3$, dấu bằng khi $x = 16$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-16$', 0), (@q, 'B', N'$3$', 1), (@q, 'C', N'$35$', 0), (@q, 'D', N'$19$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Tìm giá trị nhỏ nhất của biểu thức $P = x - 8\sqrt{x} - 2$ với $x \ge 0$.', 4, N'$P = (\sqrt{x})^2 - 2\cdot 4\cdot\sqrt{x} + 16 - 18 = (\sqrt{x} - 4)^2 - 18 \ge -18$.<br>Dấu "=" xảy ra khi $\sqrt{x} = 4 \Leftrightarrow x = 16$.<br>Vậy giá trị nhỏ nhất của $P$ là $-18$, đạt được khi $x = 16$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Cho $P = \frac{\sqrt{x} + 3}{\sqrt{x} - 3}$ với $x \ge 0,\ x \ne 9$. Tìm $x$ để $P = 3$.', 4, N'$P = 3 \Leftrightarrow \sqrt{x} + 3 = 3(\sqrt{x} - 3) \Leftrightarrow 2\sqrt{x} = 12 \Leftrightarrow \sqrt{x} = 6$<br>$\Leftrightarrow x = 36$ (thỏa mãn điều kiện).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Không dùng máy tính, so sánh $\sqrt{7} + \sqrt{6}$ và $6$.', 4, N'Hai số đều dương nên so sánh bình phương: $(\sqrt{7} + \sqrt{6})^2 = 13 + 2\sqrt{42}$ và $6^2 = 36$.<br>So sánh $2\sqrt{42}$ với $23$: $(2\sqrt{42})^2 = 168$ và $23^2 = 529$, mà $168 \lt 529$.<br>Vậy $\sqrt{7} + \sqrt{6} \lt 6$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(3, 'essay', N'Tìm giá trị nhỏ nhất của biểu thức $P = x - 10\sqrt{x} + 19$ với $x \ge 0$.', 4, N'$P = (\sqrt{x})^2 - 2\cdot 5\cdot\sqrt{x} + 25 - 6 = (\sqrt{x} - 5)^2 - 6 \ge -6$.<br>Dấu "=" xảy ra khi $\sqrt{x} = 5 \Leftrightarrow x = 25$.<br>Vậy giá trị nhỏ nhất của $P$ là $-6$, đạt được khi $x = 25$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Giá trị của $\sqrt[3]{-125}$ là:', 1, N'Vì $(-5)^3 = -125$ nên $\sqrt[3]{-125} = -5$.', 'manual', @admin);
