INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Khẳng định nào sau đây là đúng?', 1, N'Mỗi số thực có đúng một căn bậc ba; $\sqrt[3]{729} = 9$ vì $9^3 = 729$. Căn bậc ba của số âm vẫn xác định.', 'manual', @admin);
