INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Sắp xếp các số sau theo thứ tự tăng dần: $\sqrt[3]{18}$, $\sqrt[3]{48}$, $3\sqrt[3]{5}$.', 3, N'Ta có $3\sqrt[3]{5} = \sqrt[3]{135}$. So sánh các số dưới dấu căn: $18 \lt 48 \lt 135$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$3\sqrt[3]{5} \lt \sqrt[3]{48} \lt \sqrt[3]{18}$', 0), (@q, 'B', N'$\sqrt[3]{18} \lt \sqrt[3]{48} \lt 3\sqrt[3]{5}$', 1), (@q, 'C', N'$\sqrt[3]{48} \lt \sqrt[3]{18} \lt 3\sqrt[3]{5}$', 0), (@q, 'D', N'$\sqrt[3]{18} \lt 3\sqrt[3]{5} \lt \sqrt[3]{48}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Nghiệm của phương trình $\sqrt[3]{x - 7} = -3$ là:', 3, N'Lập phương hai vế: $x - 7 = -27 \Leftrightarrow x = -20$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = 20$', 0), (@q, 'B', N'$x = -20$', 1), (@q, 'C', N'$x = 16$', 0), (@q, 'D', N'$x = -34$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Sắp xếp các số sau theo thứ tự tăng dần: $\sqrt[3]{29}$, $\sqrt[3]{37}$, $3\sqrt[3]{3}$.', 3, N'Ta có $3\sqrt[3]{3} = \sqrt[3]{81}$. So sánh các số dưới dấu căn: $29 \lt 37 \lt 81$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\sqrt[3]{29} \lt \sqrt[3]{37} \lt 3\sqrt[3]{3}$', 1), (@q, 'B', N'$3\sqrt[3]{3} \lt \sqrt[3]{37} \lt \sqrt[3]{29}$', 0), (@q, 'C', N'$\sqrt[3]{29} \lt 3\sqrt[3]{3} \lt \sqrt[3]{37}$', 0), (@q, 'D', N'$\sqrt[3]{37} \lt \sqrt[3]{29} \lt 3\sqrt[3]{3}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Giải phương trình $\sqrt[3]{3x + 1} = -2$.', 3, N'Lập phương hai vế: $3x + 1 = -8 \Leftrightarrow 3x = -9 \Leftrightarrow x = -3$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'So sánh $4\sqrt[3]{3}$ và $\sqrt[3]{195}$.', 3, N'Đưa thừa số vào trong dấu căn: $4\sqrt[3]{3} = \sqrt[3]{4^3\cdot 3} = \sqrt[3]{192}$.<br>Vì $192 \lt 195$ nên $4\sqrt[3]{3} \lt \sqrt[3]{195}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Tính giá trị biểu thức $B = \sqrt{121} + \sqrt[3]{-27} - \sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8}$.', 3, N'$\sqrt{121} = 11$, $\sqrt[3]{-27} = -3$, $\sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8} = \frac{1}{2}\cdot(-2) = -1$.<br>$B = 11 + (-3) - (-1) = 9$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Giải phương trình $\sqrt[3]{2x - 3} = 3$.', 3, N'Lập phương hai vế: $2x - 3 = 27 \Leftrightarrow 2x = 30 \Leftrightarrow x = 15$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'So sánh $2\sqrt[3]{3}$ và $\sqrt[3]{26}$.', 3, N'Đưa thừa số vào trong dấu căn: $2\sqrt[3]{3} = \sqrt[3]{2^3\cdot 3} = \sqrt[3]{24}$.<br>Vì $24 \lt 26$ nên $2\sqrt[3]{3} \lt \sqrt[3]{26}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Tính giá trị biểu thức $B = \sqrt{4} + \sqrt[3]{1} - \sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8}$.', 3, N'$\sqrt{4} = 2$, $\sqrt[3]{1} = 1$, $\sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8} = \frac{1}{2}\cdot(-2) = -1$.<br>$B = 2 + 1 - (-1) = 4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Giải phương trình $\sqrt[3]{x + 5} = -1$.', 3, N'Lập phương hai vế: $x + 5 = -1 \Leftrightarrow x = -6 \Leftrightarrow x = -6$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'So sánh $3\sqrt[3]{2}$ và $\sqrt[3]{57}$.', 3, N'Đưa thừa số vào trong dấu căn: $3\sqrt[3]{2} = \sqrt[3]{3^3\cdot 2} = \sqrt[3]{54}$.<br>Vì $54 \lt 57$ nên $3\sqrt[3]{2} \lt \sqrt[3]{57}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Tính giá trị biểu thức $B = \sqrt{64} + \sqrt[3]{125} - \sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8}$.', 3, N'$\sqrt{64} = 8$, $\sqrt[3]{125} = 5$, $\sqrt[3]{\frac{1}{8}}\cdot \sqrt[3]{-8} = \frac{1}{2}\cdot(-2) = -1$.<br>$B = 8 + 5 - (-1) = 14$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'mcq', N'Nghiệm của phương trình $\sqrt[3]{x^3 + 9x^2 - 108} = x + 3$ là:', 4, N'Lập phương hai vế: $x^3 + 9x^2 - 108 = x^3 + 9x^2 + 27x + 27$ $\Leftrightarrow 27x = -135 \Leftrightarrow x = -5$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = -5$', 1), (@q, 'B', N'$x = -108$', 0), (@q, 'C', N'$x = -4$', 0), (@q, 'D', N'$x = 5$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Giải phương trình $\sqrt[3]{x^3 - 6x^2 - 32} = x - 2$.', 4, N'Lập phương hai vế (phép lập phương không cần điều kiện):<br>$x^3 - 6x^2 - 32 = \left(x - 2\right)^3 = x^3 - 6x^2 + 12x - 8$<br>$\Leftrightarrow 12x = -24 \Leftrightarrow x = -2$. Vậy phương trình có nghiệm $x = -2$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Tính giá trị biểu thức $A = \left(\sqrt[3]{5} + \sqrt[3]{10}\right)\left(\sqrt[3]{25} - \sqrt[3]{50} + \sqrt[3]{100}\right)$.', 4, N'Đặt $u = \sqrt[3]{5},\ v = \sqrt[3]{10}$ thì $\sqrt[3]{25} = u^2$, $\sqrt[3]{50} = uv$, $\sqrt[3]{100} = v^2$.<br>$A = (u + v)(u^2 - uv + v^2) = u^3 + v^3 = 5 + 10 = 15$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Chứng minh rằng $\sqrt[3]{4} + \sqrt[3]{2} \gt \sqrt[3]{6}$.', 4, N'Đặt $u = \sqrt[3]{4} \gt 0,\ v = \sqrt[3]{2} \gt 0$. Ta có $(u + v)^3 = u^3 + v^3 + 3uv(u + v) \gt u^3 + v^3 = 4 + 2 = 6$.<br>Do đó $u + v \gt \sqrt[3]{6}$, tức $\sqrt[3]{4} + \sqrt[3]{2} \gt \sqrt[3]{6}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(4, 'essay', N'Giải phương trình $\sqrt[3]{x^3 + 6x^2 - 64} = x + 2$.', 4, N'Lập phương hai vế (phép lập phương không cần điều kiện):<br>$x^3 + 6x^2 - 64 = \left(x + 2\right)^3 = x^3 + 6x^2 + 12x + 8$<br>$\Leftrightarrow 12x = -72 \Leftrightarrow x = -6$. Vậy phương trình có nghiệm $x = -6$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Cho hàm số $y = x^2$. Giá trị của hàm số tại $x = 3$ là:', 1, N'$y = 3^2 = 9$.', 'manual', @admin);
