INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Đồ thị hàm số $y = 2x^2$ là một parabol', 1, N'Parabol $y = ax^2$ có đỉnh $O$, nhận $Oy$ làm trục đối xứng; vì $a = 2 \gt 0$ nên nằm phía trên trục hoành.', 'manual', @admin);
