INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = \frac{1}{2}x^2$. Lập bảng giá trị của hàm số với $x \in \{-2; -1; 0; 1; 2\}$ và nêu tính đồng biến, nghịch biến của hàm số.', 1, N'Bảng giá trị: $x = -2 \Rightarrow y = 2$; $x = -1 \Rightarrow y = \frac{1}{2}$; $x = 0 \Rightarrow y = 0$; $x = 1 \Rightarrow y = \frac{1}{2}$; $x = 2 \Rightarrow y = 2$.<br>Vì $a = \frac{1}{2} \gt 0$ nên hàm số nghịch biến khi $x \lt 0$ và đồng biến khi $x \gt 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = -\frac{1}{2}x^2$. Lập bảng giá trị của hàm số với $x \in \{-2; -1; 0; 1; 2\}$ và nêu tính đồng biến, nghịch biến của hàm số.', 1, N'Bảng giá trị: $x = -2 \Rightarrow y = -2$; $x = -1 \Rightarrow y = -\frac{1}{2}$; $x = 0 \Rightarrow y = 0$; $x = 1 \Rightarrow y = -\frac{1}{2}$; $x = 2 \Rightarrow y = -2$.<br>Vì $a = -\frac{1}{2} \lt 0$ nên hàm số đồng biến khi $x \lt 0$ và nghịch biến khi $x \gt 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = 2x^2$. Lập bảng giá trị của hàm số với $x \in \{-2; -1; 0; 1; 2\}$ và nêu tính đồng biến, nghịch biến của hàm số.', 1, N'Bảng giá trị: $x = -2 \Rightarrow y = 8$; $x = -1 \Rightarrow y = 2$; $x = 0 \Rightarrow y = 0$; $x = 1 \Rightarrow y = 2$; $x = 2 \Rightarrow y = 8$.<br>Vì $a = 2 \gt 0$ nên hàm số nghịch biến khi $x \lt 0$ và đồng biến khi $x \gt 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Đồ thị hàm số $y = ax^2$ đi qua điểm $A(-4; -8)$. Giá trị của $a$ là:', 2, N'Thay tọa độ $A$: $-8 = a\cdot (-4)^2 = 16a \Rightarrow a = -\frac{1}{2}$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-2$', 0), (@q, 'B', N'$-\frac{1}{2}$', 1), (@q, 'C', N'$2$', 0), (@q, 'D', N'$\frac{1}{2}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Các điểm thuộc parabol $y = x^2$ có tung độ bằng $25$ có hoành độ là:', 2, N'$x^2 = 25 \Leftrightarrow x = \pm 5$.', 'manual', @admin);
