INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Đồ thị hàm số $y = ax^2$ đi qua điểm $A(-2; -4)$. Giá trị của $a$ là:', 2, N'Thay tọa độ $A$: $-4 = a\cdot (-2)^2 = 4a \Rightarrow a = -1$.', 'manual', @admin);
