INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Các điểm thuộc parabol $y = -2x^2$ có tung độ bằng $-72$ có hoành độ là:', 2, N'$-2x^2 = -72 \Leftrightarrow x^2 = 36 \Leftrightarrow x = \pm 6$.', 'manual', @admin);
