INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$2$', 1), (@q, 'B', N'$\frac{1}{2}$', 0), (@q, 'C', N'$-8$', 0), (@q, 'D', N'$-2$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Các điểm thuộc parabol $y = -3x^2$ có tung độ bằng $-48$ có hoành độ là:', 2, N'$-3x^2 = -48 \Leftrightarrow x^2 = 16 \Leftrightarrow x = \pm 4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = -4$', 0), (@q, 'B', N'$x = \pm 4$', 1), (@q, 'C', N'$x = 4$', 0), (@q, 'D', N'$x = \pm 16$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Đồ thị hàm số $y = ax^2$ đi qua điểm $A(4; -8)$. Giá trị của $a$ là:', 2, N'Thay tọa độ $A$: $-8 = a\cdot 4^2 = 16a \Rightarrow a = -\frac{1}{2}$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\frac{1}{2}$', 0), (@q, 'B', N'$-\frac{1}{2}$', 1), (@q, 'C', N'$-2$', 0), (@q, 'D', N'$-8$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Các điểm thuộc parabol $y = 3x^2$ có tung độ bằng $108$ có hoành độ là:', 2, N'$3x^2 = 108 \Leftrightarrow x^2 = 36 \Leftrightarrow x = \pm 6$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = 6$', 0), (@q, 'B', N'$x = \pm 36$', 0), (@q, 'C', N'$x = \pm 6$', 1), (@q, 'D', N'$x = -6$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = ax^2$ có đồ thị đi qua điểm $A(1; -2)$.<br>a) Tìm $a$.<br>b) Điểm $B(2; -8)$ có thuộc đồ thị hàm số không?', 2, N'a) $-2 = a\cdot 1^2 \Rightarrow a = -2$, hàm số $y = -2x^2$.<br>b) Với $x = 2$: $y = -2\cdot 2^2 = -8$. Vì $-8 = -8$ nên $B$ thuộc đồ thị.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Điểm $M(1; -2)$ thuộc parabol $y = -2x^2$. Tìm điểm $N$ thuộc parabol đối xứng với $M$ qua trục $Oy$ và tính độ dài $MN$.', 2, N'Parabol nhận $Oy$ làm trục đối xứng nên $N(-1; -2)$ (kiểm tra: $-2\cdot (-1)^2 = -2$).<br>$MN = |1 - (-1)| = 2$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = ax^2$ có đồ thị đi qua điểm $A(-2; 8)$.<br>a) Tìm $a$.<br>b) Điểm $B(2; 8)$ có thuộc đồ thị hàm số không?', 2, N'a) $8 = a\cdot (-2)^2 \Rightarrow a = 2$, hàm số $y = 2x^2$.<br>b) Với $x = 2$: $y = 2\cdot 2^2 = 8$. Vì $8 = 8$ nên $B$ thuộc đồ thị.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Điểm $M(2; -12)$ thuộc parabol $y = -3x^2$. Tìm điểm $N$ thuộc parabol đối xứng với $M$ qua trục $Oy$ và tính độ dài $MN$.', 2, N'Parabol nhận $Oy$ làm trục đối xứng nên $N(-2; -12)$ (kiểm tra: $-3\cdot (-2)^2 = -12$).<br>$MN = |2 - (-2)| = 4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Cho hàm số $y = ax^2$ có đồ thị đi qua điểm $A(2; -8)$.<br>a) Tìm $a$.<br>b) Điểm $B(-5; -52)$ có thuộc đồ thị hàm số không?', 2, N'a) $-8 = a\cdot 2^2 \Rightarrow a = -2$, hàm số $y = -2x^2$.<br>b) Với $x = -5$: $y = -2\cdot (-5)^2 = -50$. Vì $-50 \ne -52$ nên $B$ không thuộc đồ thị.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Hoành độ giao điểm của parabol $y = 2x^2$ và đường thẳng $y = 8x - 6$ là:', 3, N'Phương trình hoành độ: $2x^2 = 8x - 6 \Leftrightarrow 2x^2 - 8x + 6 = 0 \Leftrightarrow x = 1$ hoặc $x = 3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = 1$', 0), (@q, 'B', N'$x = 1;\ x = 3$', 1), (@q, 'C', N'$x = 3$', 0), (@q, 'D', N'$x = -1;\ x = -3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Số giao điểm của parabol $y = -x^2$ và đường thẳng $y = x$ là:', 3, N'Xét $-x^2 - x = 0$ có $\Delta = (-1)^2 - 4\cdot (-1)\cdot 0 = 1$ $\gt 0$ nên có 2 giao điểm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$1$', 0), (@q, 'B', N'$2$', 1), (@q, 'C', N'$3$', 0), (@q, 'D', N'$0$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Hoành độ giao điểm của parabol $y = -2x^2$ và đường thẳng $y = -14x + 20$ là:', 3, N'Phương trình hoành độ: $-2x^2 = -14x + 20 \Leftrightarrow -2x^2 + 14x - 20 = 0 \Leftrightarrow x = 2$ hoặc $x = 5$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = 5$', 0), (@q, 'B', N'$x = 2;\ x = 5$', 1), (@q, 'C', N'$x = -2;\ x = -5$', 0), (@q, 'D', N'$x = 2$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Số giao điểm của parabol $y = x^2$ và đường thẳng $y = -4x - 7$ là:', 3, N'Xét $x^2 + 4x + 7 = 0$ có $\Delta = 4^2 - 4\cdot 1\cdot 7 = -12$ $\lt 0$ nên không có giao điểm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$0$', 1), (@q, 'B', N'$1$', 0), (@q, 'C', N'$3$', 0), (@q, 'D', N'$2$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Hoành độ giao điểm của parabol $y = -x^2$ và đường thẳng $y = -2x - 15$ là:', 3, N'Phương trình hoành độ: $-x^2 = -2x - 15 \Leftrightarrow -x^2 + 2x + 15 = 0 \Leftrightarrow x = -3$ hoặc $x = 5$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$x = -3$', 0), (@q, 'B', N'$x = -3;\ x = 5$', 1), (@q, 'C', N'$x = 3;\ x = -5$', 0), (@q, 'D', N'$x = 5$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Số giao điểm của parabol $y = 2x^2$ và đường thẳng $y = 6x + 4$ là:', 3, N'Xét $2x^2 - 6x - 4 = 0$ có $\Delta = (-6)^2 - 4\cdot 2\cdot (-4) = 68$ $\gt 0$ nên có 2 giao điểm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$3$', 0), (@q, 'B', N'$0$', 0), (@q, 'C', N'$1$', 0), (@q, 'D', N'$2$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm tọa độ giao điểm của parabol $(P): y = 2x^2$ và đường thẳng $(d): y = 32$.', 3, N'Phương trình hoành độ giao điểm: $2x^2 = 32 \Leftrightarrow 2x^2 - 32 = 0$.<br>Giải được $x = -4$ hoặc $x = 4$.<br>Với $x = -4$: $y = 32$; với $x = 4$: $y = 32$.<br>Vậy giao điểm là $(-4; 32)$ và $(4; 32)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Quãng đường rơi tự do của một vật được tính theo công thức $s = \frac{1}{2}t^2$ ($s$ tính bằng mét, $t$ tính bằng giây). a) Sau $8$ giây vật rơi được bao nhiêu mét?<br>b) Sau bao lâu vật rơi được $128$ m?', 3, N'a) $s = \frac{1}{2}\cdot 8^2 = 32$ (m).<br>b) $\frac{1}{2}t^2 = 128 \Leftrightarrow t^2 = 256 \Leftrightarrow t = 16$ (giây) (vì $t \gt 0$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm tọa độ giao điểm của parabol $(P): y = x^2$ và đường thẳng $(d): y = 7x - 12$.', 3, N'Phương trình hoành độ giao điểm: $x^2 = 7x - 12 \Leftrightarrow x^2 - 7x + 12 = 0$.<br>Giải được $x = 3$ hoặc $x = 4$.<br>Với $x = 3$: $y = 9$; với $x = 4$: $y = 16$.<br>Vậy giao điểm là $(3; 9)$ và $(4; 16)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Quãng đường rơi tự do của một vật được tính theo công thức $s = \frac{1}{4}t^2$ ($s$ tính bằng mét, $t$ tính bằng giây). a) Sau $2$ giây vật rơi được bao nhiêu mét?<br>b) Sau bao lâu vật rơi được $4$ m?', 3, N'a) $s = \frac{1}{4}\cdot 2^2 = 1$ (m).<br>b) $\frac{1}{4}t^2 = 4 \Leftrightarrow t^2 = 16 \Leftrightarrow t = 4$ (giây) (vì $t \gt 0$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm tọa độ giao điểm của parabol $(P): y = 2x^2$ và đường thẳng $(d): y = 14x - 20$.', 3, N'Phương trình hoành độ giao điểm: $2x^2 = 14x - 20 \Leftrightarrow 2x^2 - 14x + 20 = 0$.<br>Giải được $x = 2$ hoặc $x = 5$.<br>Với $x = 2$: $y = 8$; với $x = 5$: $y = 50$.<br>Vậy giao điểm là $(2; 8)$ và $(5; 50)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Quãng đường rơi tự do của một vật được tính theo công thức $s = 3t^2$ ($s$ tính bằng mét, $t$ tính bằng giây). a) Sau $5$ giây vật rơi được bao nhiêu mét?<br>b) Sau bao lâu vật rơi được $300$ m?', 3, N'a) $s = 3\cdot 5^2 = 75$ (m).<br>b) $3t^2 = 300 \Leftrightarrow t^2 = 100 \Leftrightarrow t = 10$ (giây) (vì $t \gt 0$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm tọa độ giao điểm của parabol $(P): y = -x^2$ và đường thẳng $(d): y = -6x + 8$.', 3, N'Phương trình hoành độ giao điểm: $-x^2 = -6x + 8 \Leftrightarrow -x^2 + 6x - 8 = 0$.<br>Giải được $x = 2$ hoặc $x = 4$.<br>Với $x = 2$: $y = -4$; với $x = 4$: $y = -16$.<br>Vậy giao điểm là $(2; -4)$ và $(4; -16)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Quãng đường rơi tự do của một vật được tính theo công thức $s = 3t^2$ ($s$ tính bằng mét, $t$ tính bằng giây). a) Sau $8$ giây vật rơi được bao nhiêu mét?<br>b) Sau bao lâu vật rơi được $768$ m?', 3, N'a) $s = 3\cdot 8^2 = 192$ (m).<br>b) $3t^2 = 768 \Leftrightarrow t^2 = 256 \Leftrightarrow t = 16$ (giây) (vì $t \gt 0$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm tọa độ giao điểm của parabol $(P): y = -x^2$ và đường thẳng $(d): y = -3x - 4$.', 3, N'Phương trình hoành độ giao điểm: $-x^2 = -3x - 4 \Leftrightarrow -x^2 + 3x + 4 = 0$.<br>Giải được $x = -1$ hoặc $x = 4$.<br>Với $x = -1$: $y = -1$; với $x = 4$: $y = -16$.<br>Vậy giao điểm là $(-1; -1)$ và $(4; -16)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'mcq', N'Tìm $m$ để đường thẳng $y = 6x + m$ tiếp xúc với parabol $y = 3x^2$.', 4, N'$3x^2 - 6x - m = 0$ có nghiệm kép $\Leftrightarrow \Delta = 36 + 12m = 0 \Leftrightarrow m = -3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m = 3$', 0), (@q, 'B', N'$m \gt -3$', 0), (@q, 'C', N'$m = -2$', 0), (@q, 'D', N'$m = -3$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm $m$ để đường thẳng $(d): y = -4x + m$ tiếp xúc với parabol $(P): y = -x^2$. Tìm tọa độ tiếp điểm.', 4, N'Phương trình hoành độ giao điểm: $-x^2 + 4x - m = 0$ (1).<br>$(d)$ tiếp xúc $(P)$ khi (1) có nghiệm kép: $\Delta = 4^2 + 4\cdot (-1)\cdot m = 16 - 4m = 0 \Leftrightarrow m = 4$.<br>Khi đó nghiệm kép $x = \frac{-4}{-2} = 2$, $y = -4$. Tiếp điểm $(2; -4)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm $m$ để đường thẳng $(d): y = -x + m$ cắt parabol $(P): y = 2x^2$ tại hai điểm phân biệt.', 4, N'Phương trình hoành độ giao điểm: $2x^2 + x - m = 0$.<br>Cần $\Delta = 1 + 8m \gt 0 \Leftrightarrow m \gt -\frac{1}{8}$.<br>Vậy $m \gt -\frac{1}{8}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Parabol $(P): y = x^2$ cắt đường thẳng $(d): y = x + 6$ tại hai điểm $A, B$. Tính diện tích tam giác $OAB$ ($O$ là gốc tọa độ).', 4, N'Hoành độ giao điểm là nghiệm của $x^2 - x - 6 = 0$, được $x = -2$ hoặc $x = 3$.<br>$A(-2; 4)$, $B(3; 9)$.<br>$S_{OAB} = \frac{1}{2}|x_Ay_B - x_By_A| = \frac{1}{2}|-2\cdot 9 - 3\cdot 4| = 15$ (đơn vị diện tích).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(5, 'essay', N'Tìm $m$ để đường thẳng $(d): y = 6x + m$ tiếp xúc với parabol $(P): y = -x^2$. Tìm tọa độ tiếp điểm.', 4, N'Phương trình hoành độ giao điểm: $-x^2 - 6x - m = 0$ (1).<br>$(d)$ tiếp xúc $(P)$ khi (1) có nghiệm kép: $\Delta = (-6)^2 + 4\cdot (-1)\cdot m = 36 - 4m = 0 \Leftrightarrow m = 9$.<br>Khi đó nghiệm kép $x = \frac{6}{-2} = -3$, $y = -9$. Tiếp điểm $(-3; -9)$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình nào sau đây là phương trình bậc hai một ẩn?', 1, N'Phương trình bậc hai một ẩn có dạng $ax^2 + bx + c = 0$ với $a \ne 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-3x^2 + \frac{1}{x} = 1$', 0), (@q, 'B', N'$-3x^3 + 4x = 0$', 0), (@q, 'C', N'$4x = 0$', 0), (@q, 'D', N'$-3x^2 + 4x = 0$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Các hệ số $a, b, c$ của phương trình $-7x^2 + 9x - 9 = 0$ là:', 1, N'So sánh với dạng $ax^2 + bx + c = 0$: $a = -7,\ b = 9,\ c = -9$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$a = -7,\ b = 9,\ c = -9$', 1), (@q, 'B', N'$a = 9,\ b = -7,\ c = -9$', 0), (@q, 'C', N'$a = -7,\ b = 9,\ c = 9$', 0), (@q, 'D', N'$a = -7,\ b = -9,\ c = -9$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Biệt thức $\Delta$ của phương trình $-x^2 - 3x - 8 = 0$ bằng:', 1, N'$\Delta = b^2 - 4ac = (-3)^2 - 4\cdot (-1)\cdot (-8) = -23$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$23$', 0), (@q, 'B', N'$41$', 0), (@q, 'C', N'$-23$', 1), (@q, 'D', N'$-35$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình $3x^2 + 2x + 3 = 0$', 1, N'$\Delta = 2^2 - 4\cdot 3\cdot 3 = -32$ $\lt 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Có hai nghiệm phân biệt', 0), (@q, 'B', N'Có nghiệm kép', 0), (@q, 'C', N'Có vô số nghiệm', 0), (@q, 'D', N'Vô nghiệm', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình nào sau đây là phương trình bậc hai một ẩn?', 1, N'Phương trình bậc hai một ẩn có dạng $ax^2 + bx + c = 0$ với $a \ne 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-3x^2 + \frac{1}{x} = 1$', 0), (@q, 'B', N'$7x = 0$', 0), (@q, 'C', N'$-3x^2 + 7x = 0$', 1), (@q, 'D', N'$-3x^3 + 7x = 0$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Các hệ số $a, b, c$ của phương trình $4x^2 - 9x - 3 = 0$ là:', 1, N'So sánh với dạng $ax^2 + bx + c = 0$: $a = 4,\ b = -9,\ c = -3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$a = 4,\ b = -9,\ c = -3$', 1), (@q, 'B', N'$a = 4,\ b = -9,\ c = 3$', 0), (@q, 'C', N'$a = 4,\ b = 9,\ c = -3$', 0), (@q, 'D', N'$a = -9,\ b = 4,\ c = -3$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Biệt thức $\Delta$ của phương trình $-5x^2 + x - 3 = 0$ bằng:', 1, N'$\Delta = b^2 - 4ac = 1^2 - 4\cdot (-5)\cdot (-3) = -59$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-59$', 1), (@q, 'B', N'$-29$', 0), (@q, 'C', N'$61$', 0), (@q, 'D', N'$59$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình $-4x^2 + 9x - 2 = 0$', 1, N'$\Delta = 9^2 - 4\cdot (-4)\cdot (-2) = 49$ $\gt 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Có vô số nghiệm', 0), (@q, 'B', N'Vô nghiệm', 0), (@q, 'C', N'Có hai nghiệm phân biệt', 1), (@q, 'D', N'Có nghiệm kép', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Các hệ số $a, b, c$ của phương trình $7x^2 - 2x - 7 = 0$ là:', 1, N'So sánh với dạng $ax^2 + bx + c = 0$: $a = 7,\ b = -2,\ c = -7$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$a = 7,\ b = -2,\ c = -7$', 1), (@q, 'B', N'$a = -2,\ b = 7,\ c = -7$', 0), (@q, 'C', N'$a = 7,\ b = -2,\ c = 7$', 0), (@q, 'D', N'$a = 7,\ b = 2,\ c = -7$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Biệt thức $\Delta$ của phương trình $-3x^2 - 2x + 7 = 0$ bằng:', 1, N'$\Delta = b^2 - 4ac = (-2)^2 - 4\cdot (-3)\cdot 7 = 88$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$82$', 0), (@q, 'B', N'$-80$', 0), (@q, 'C', N'$-88$', 0), (@q, 'D', N'$88$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình $2x^2 + 4x + 1 = 0$', 1, N'$\Delta = 4^2 - 4\cdot 2\cdot 1 = 8$ $\gt 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'Vô nghiệm', 0), (@q, 'B', N'Có hai nghiệm phân biệt', 1), (@q, 'C', N'Có nghiệm kép', 0), (@q, 'D', N'Có vô số nghiệm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Các hệ số $a, b, c$ của phương trình $7x^2 - 5x + 4 = 0$ là:', 1, N'So sánh với dạng $ax^2 + bx + c = 0$: $a = 7,\ b = -5,\ c = 4$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$a = -5,\ b = 7,\ c = 4$', 0), (@q, 'B', N'$a = 7,\ b = -5,\ c = -4$', 0), (@q, 'C', N'$a = 7,\ b = -5,\ c = 4$', 1), (@q, 'D', N'$a = 7,\ b = 5,\ c = 4$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Không giải phương trình, hãy xác định các hệ số $a, b, c$, tính $\Delta$ và cho biết số nghiệm của phương trình $-4x^2 - 3x - 4 = 0$.', 1, N'$a = -4,\ b = -3,\ c = -4$.<br>$\Delta = (-3)^2 - 4\cdot (-4)\cdot (-4) = -55$.<br>Vì $\Delta \lt 0$ nên phương trình vô nghiệm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Không giải phương trình, hãy xác định các hệ số $a, b, c$, tính $\Delta$ và cho biết số nghiệm của phương trình $3x^2 + 5x - 4 = 0$.', 1, N'$a = 3,\ b = 5,\ c = -4$.<br>$\Delta = 5^2 - 4\cdot 3\cdot (-4) = 73$.<br>Vì $\Delta \gt 0$ nên phương trình có hai nghiệm phân biệt.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Không giải phương trình, hãy xác định các hệ số $a, b, c$, tính $\Delta$ và cho biết số nghiệm của phương trình $5x^2 - 8x + 3 = 0$.', 1, N'$a = 5,\ b = -8,\ c = 3$.<br>$\Delta = (-8)^2 - 4\cdot 5\cdot 3 = 4$.<br>Vì $\Delta \gt 0$ nên phương trình có hai nghiệm phân biệt.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Tập nghiệm của phương trình $3x^2 + 12x - 36 = 0$ là:', 2, N'$\Delta = 576$, $\sqrt{\Delta} = 24$. Hai nghiệm: $x_1 = -6,\ x_2 = 2$.', 'manual', @admin);
