INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $2x^2 - 6 = 0$. Tích $x_1x_2$ bằng:', 2, N'$\Delta = 48 \ge 0$. Theo định lí Viète: $x_1x_2 = \frac{c}{a} = -3$.', 'manual', @admin);
