INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $-3x^2 + 8x - 5 = 0$. Tích $x_1x_2$ bằng:', 2, N'$\Delta = 4 \ge 0$. Theo định lí Viète: $x_1x_2 = \frac{c}{a} = \frac{5}{3}$.', 'manual', @admin);
