INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Nghiệm của phương trình $-3x^2 + 5x + 8 = 0$ là:', 2, N'Vì $a - b + c = -3 - 5 + 8 = 0$ nên $x_1 = -1,\ x_2 = -\frac{c}{a} = \frac{8}{3}$.', 'manual', @admin);
