INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $-2x^2 - 8x - 1 = 0$. Tích $x_1x_2$ bằng:', 2, N'$\Delta = 56 \ge 0$. Theo định lí Viète: $x_1x_2 = \frac{c}{a} = \frac{1}{2}$.', 'manual', @admin);
