INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Nghiệm của phương trình $2x^2 - 5x - 7 = 0$ là:', 2, N'Vì $a - b + c = 2 - (-5) + (-7) = 0$ nên $x_1 = -1,\ x_2 = -\frac{c}{a} = \frac{7}{2}$.', 'manual', @admin);
