INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Giải phương trình $2x^2 + 3x - 5 = 0$.', 2, N'$a = 2,\ b = 3,\ c = -5$; $\Delta = 3^2 - 4\cdot 2\cdot (-5) = 49 \gt 0$, $\sqrt{\Delta} = 7$.<br>$x_1 = \frac{-3 + 7}{4} = 1$; $x_2 = \frac{-3 - 7}{4} = -\frac{5}{2}$.<br>Vậy $S = \{-\frac{5}{2}; 1\}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Giải phương trình $-3x^2 + 3x = 0$.', 2, N'Đặt nhân tử chung: $x(-3x + 3) = 0 \Leftrightarrow x = 0$ hoặc $x = 1$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Giải phương trình $x^2 - x = 0$.', 2, N'$a = 1,\ b = -1,\ c = 0$; $\Delta = (-1)^2 - 4\cdot 1\cdot 0 = 1 \gt 0$, $\sqrt{\Delta} = 1$.<br>$x_1 = \frac{1 + 1}{2} = 1$; $x_2 = \frac{1 - 1}{2} = 0$.<br>Vậy $S = \{0; 1\}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Giải phương trình $x^2 - 8x = 0$.', 2, N'Đặt nhân tử chung: $x(x - 8) = 0 \Leftrightarrow x = 0$ hoặc $x = 8$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Giải phương trình $-2x^2 - 2x + 60 = 0$.', 2, N'$a = -2,\ b = -2,\ c = 60$; $\Delta = (-2)^2 - 4\cdot (-2)\cdot 60 = 484 \gt 0$, $\sqrt{\Delta} = 22$.<br>$x_1 = \frac{2 + 22}{-4} = -6$; $x_2 = \frac{2 - 22}{-4} = 5$.<br>Vậy $S = \{-6; 5\}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $x^2 - 9x + 7 = 0$. Giá trị của $x_1^2 + x_2^2$ là:', 3, N'Viète: $x_1 + x_2 = 9,\ x_1x_2 = 7$. $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = 81 - 14 = 67$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$74$', 0), (@q, 'B', N'$95$', 0), (@q, 'C', N'$-5$', 0), (@q, 'D', N'$67$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $-2x^2 + 7x + 6 = 0$. Giá trị của $\frac{1}{x_1} + \frac{1}{x_2}$ là:', 3, N'Viète: $x_1 + x_2 = \frac{7}{2},\ x_1x_2 = -3$. $\frac{1}{x_1} + \frac{1}{x_2} = \frac{x_1 + x_2}{x_1x_2} = -\frac{7}{6}$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-\frac{7}{6}$', 1), (@q, 'B', N'$\frac{7}{6}$', 0), (@q, 'C', N'$-\frac{21}{2}$', 0), (@q, 'D', N'$-\frac{6}{7}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Một mảnh vườn hình chữ nhật có chu vi $46$ m và diện tích $102$ m$^2$. Chiều dài và chiều rộng của mảnh vườn lần lượt là:', 3, N'Chiều dài và chiều rộng là nghiệm của $x^2 - 23x + 102 = 0$, được $x = 17$ và $x = 6$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$18$ m và $5$ m', 0), (@q, 'B', N'$23$ m và $6$ m', 0), (@q, 'C', N'$19$ m và $6$ m', 0), (@q, 'D', N'$17$ m và $6$ m', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $x^2 - 6x - 7 = 0$. Giá trị của $x_1^2 + x_2^2$ là:', 3, N'Viète: $x_1 + x_2 = 6,\ x_1x_2 = -7$. $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = 36 - (-14) = 50$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$22$', 0), (@q, 'B', N'$43$', 0), (@q, 'C', N'$50$', 1), (@q, 'D', N'$20$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Gọi $x_1, x_2$ là hai nghiệm của phương trình $-3x^2 - 5x - 2 = 0$. Giá trị của $\frac{1}{x_1} + \frac{1}{x_2}$ là:', 3, N'Viète: $x_1 + x_2 = -\frac{5}{3},\ x_1x_2 = \frac{2}{3}$. $\frac{1}{x_1} + \frac{1}{x_2} = \frac{x_1 + x_2}{x_1x_2} = -\frac{5}{2}$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-\frac{10}{9}$', 0), (@q, 'B', N'$-\frac{2}{5}$', 0), (@q, 'C', N'$-\frac{5}{2}$', 1), (@q, 'D', N'$\frac{5}{2}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Một mảnh vườn hình chữ nhật có chu vi $42$ m và diện tích $38$ m$^2$. Chiều dài và chiều rộng của mảnh vườn lần lượt là:', 3, N'Chiều dài và chiều rộng là nghiệm của $x^2 - 21x + 38 = 0$, được $x = 19$ và $x = 2$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$19$ m và $2$ m', 1), (@q, 'B', N'$20$ m và $1$ m', 0), (@q, 'C', N'$38$ m và $2$ m', 0), (@q, 'D', N'$21$ m và $2$ m', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm hai số tự nhiên liên tiếp có tích bằng $90$.', 3, N'Gọi hai số là $x$ và $x + 1$ ($x \in \mathbb{N}$). Ta có $x(x + 1) = 90 \Leftrightarrow x^2 + x - 90 = 0$.<br>$\Delta = 361 = 19^2$, được $x = 9$ (nhận) hoặc $x = -10$ (loại).<br>Vậy hai số là $9$ và $10$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 - 2x - 1 = 0$ có hai nghiệm $x_1, x_2$. Không giải phương trình, hãy tính:<br>a) $x_1^2 + x_2^2$;<br>b) $x_1^3 + x_2^3$.', 3, N'$\Delta = 8 \gt 0$. Theo Viète: $x_1 + x_2 = 2,\ x_1x_2 = -1$.<br>a) $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = 2^2 - 2\cdot (-1) = 6$.<br>b) $x_1^3 + x_2^3 = (x_1 + x_2)^3 - 3x_1x_2(x_1 + x_2) = 2^3 - 3\cdot (-1)\cdot 2 = 14$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm hai số tự nhiên liên tiếp có tích bằng $462$.', 3, N'Gọi hai số là $x$ và $x + 1$ ($x \in \mathbb{N}$). Ta có $x(x + 1) = 462 \Leftrightarrow x^2 + x - 462 = 0$.<br>$\Delta = 1849 = 43^2$, được $x = 21$ (nhận) hoặc $x = -22$ (loại).<br>Vậy hai số là $21$ và $22$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 + 7x + 1 = 0$ có hai nghiệm $x_1, x_2$. Không giải phương trình, hãy tính:<br>a) $x_1^2 + x_2^2$;<br>b) $x_1^3 + x_2^3$.', 3, N'$\Delta = 45 \gt 0$. Theo Viète: $x_1 + x_2 = -7,\ x_1x_2 = 1$.<br>a) $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = (-7)^2 - 2\cdot 1 = 47$.<br>b) $x_1^3 + x_2^3 = (x_1 + x_2)^3 - 3x_1x_2(x_1 + x_2) = (-7)^3 - 3\cdot 1\cdot (-7) = -322$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm hai số biết tổng của chúng bằng $18$ và tích của chúng bằng $72$.', 3, N'Hai số cần tìm là nghiệm của phương trình $x^2 - 18x + 72 = 0$.<br>$\Delta = 36 = 6^2$, giải được $x_1 = 12,\ x_2 = 6$.<br>Vậy hai số là $12$ và $6$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 - 7 = 0$ có hai nghiệm $x_1, x_2$. Không giải phương trình, hãy tính:<br>a) $x_1^2 + x_2^2$;<br>b) $x_1^3 + x_2^3$.', 3, N'$\Delta = 28 \gt 0$. Theo Viète: $x_1 + x_2 = 0,\ x_1x_2 = -7$.<br>a) $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = 0^2 - 2\cdot (-7) = 14$.<br>b) $x_1^3 + x_2^3 = (x_1 + x_2)^3 - 3x_1x_2(x_1 + x_2) = 0^3 - 3\cdot (-7)\cdot 0 = 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm hai số biết tổng của chúng bằng $-3$ và tích của chúng bằng $-10$.', 3, N'Hai số cần tìm là nghiệm của phương trình $x^2 + 3x - 10 = 0$.<br>$\Delta = 49 = 7^2$, giải được $x_1 = 2,\ x_2 = -5$.<br>Vậy hai số là $2$ và $-5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 - 5x - 12 = 0$ có hai nghiệm $x_1, x_2$. Không giải phương trình, hãy tính:<br>a) $x_1^2 + x_2^2$;<br>b) $x_1^3 + x_2^3$.', 3, N'$\Delta = 73 \gt 0$. Theo Viète: $x_1 + x_2 = 5,\ x_1x_2 = -12$.<br>a) $x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2 = 5^2 - 2\cdot (-12) = 49$.<br>b) $x_1^3 + x_2^3 = (x_1 + x_2)^3 - 3x_1x_2(x_1 + x_2) = 5^3 - 3\cdot (-12)\cdot 5 = 305$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm hai số tự nhiên liên tiếp có tích bằng $650$.', 3, N'Gọi hai số là $x$ và $x + 1$ ($x \in \mathbb{N}$). Ta có $x(x + 1) = 650 \Leftrightarrow x^2 + x - 650 = 0$.<br>$\Delta = 2601 = 51^2$, được $x = 25$ (nhận) hoặc $x = -26$ (loại).<br>Vậy hai số là $25$ và $26$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'mcq', N'Phương trình $x^2 + 2x + m = 0$ có hai nghiệm phân biệt khi và chỉ khi:', 4, N'$\Delta'' = 1 - m$. Phương trình có hai nghiệm phân biệt $\Leftrightarrow m \lt 1$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$m \lt 1$', 1), (@q, 'B', N'$m \lt -1$', 0), (@q, 'C', N'$m = 1$', 0), (@q, 'D', N'$m \gt 1$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 - 2(m + 1)x + m^2 + 6 = 0$ ($m$ là tham số). Tìm $m$ để phương trình có hai nghiệm $x_1, x_2$ thỏa mãn $x_1^2 + x_2^2 = 82$.', 4, N'$\Delta'' = (m + 1)^2 - (m^2 + 6) = 2m - 5$. Phương trình có nghiệm $\Leftrightarrow m \ge \frac{5}{2}$.<br>Viète: $x_1 + x_2 = 2(m + 1),\ x_1x_2 = m^2 + 6$.<br>$x_1^2 + x_2^2 = 4(m + 1)^2 - 2(m^2 + 6) = 2m^2 + 8m - 8 = 82$<br>$\Leftrightarrow 2m^2 + 8m - 90 = 0 \Leftrightarrow m = 5$ hoặc $m = -9$.<br>Đối chiếu điều kiện $m \ge \frac{5}{2}$: chỉ $m = 5$ thỏa mãn. Vậy $m = 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 + mx + 4 = 0$. Tìm $m$ để phương trình có một nghiệm bằng $-1$ và tìm nghiệm còn lại.', 4, N'Thay $x = -1$: $1 - m + 4 = 0 \Leftrightarrow m = 5$.<br>Theo Viète: $x_1x_2 = 4$ nên $x_2 = 4 : (-1) = -4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Tìm $m$ để phương trình $x^2 + 2x + m - 7 = 0$ có hai nghiệm trái dấu.', 4, N'Phương trình có hai nghiệm trái dấu $\Leftrightarrow ac \lt 0 \Leftrightarrow 1\cdot(m - 7) \lt 0 \Leftrightarrow m \lt 7$.<br>Vậy $m \lt 7$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(6, 'essay', N'Cho phương trình $x^2 - 2(m - 1)x + m^2 - 3 = 0$ ($m$ là tham số). Tìm $m$ để phương trình có hai nghiệm $x_1, x_2$ thỏa mãn $x_1^2 + x_2^2 = 74$.', 4, N'$\Delta'' = (m - 1)^2 - (m^2 - 3) = -2m + 4$. Phương trình có nghiệm $\Leftrightarrow m \le 2$.<br>Viète: $x_1 + x_2 = 2(m - 1),\ x_1x_2 = m^2 - 3$.<br>$x_1^2 + x_2^2 = 4(m - 1)^2 - 2(m^2 - 3) = 2m^2 - 8m + 10 = 74$<br>$\Leftrightarrow 2m^2 - 8m - 64 = 0 \Leftrightarrow m = -4$ hoặc $m = 8$.<br>Đối chiếu điều kiện $m \le 2$: chỉ $m = -4$ thỏa mãn. Vậy $m = -4$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Bất phương trình nào sau đây là bất phương trình bậc nhất một ẩn?', 1, N'Bất phương trình bậc nhất một ẩn có dạng $ax + b \gt 0$ (hoặc $\lt, \ge, \le$) với $a \ne 0$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$3x - 4 \ge 0$', 1), (@q, 'B', N'$\frac{1}{x} + 5 \ge 0$', 0), (@q, 'C', N'$0x + 5 \ge 0$', 0), (@q, 'D', N'$3x^2 - 4 \ge 0$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Giá trị nào của $x$ sau đây là một nghiệm của bất phương trình $2x + 1 \lt -3$?', 1, N'Thay $x = -6$: $2\cdot (-6) + 1 = -11 \lt -3$ (đúng). Các giá trị còn lại không thỏa mãn.', 'manual', @admin);
