INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Giá trị nào của $x$ sau đây là một nghiệm của bất phương trình $6x + 5 \ge 5$?', 1, N'Thay $x = 0$: $6\cdot 0 + 5 = 5 \ge 5$ (đúng). Các giá trị còn lại không thỏa mãn.', 'manual', @admin);
