INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Trong các số $3;\ 5;\ 0$, số nào là nghiệm của bất phương trình $4x - 5 \gt 7$?', 1, N'$x = 3$: $4\cdot 3 + (-5) = 7$ không thỏa mãn<br>$x = 5$: $4\cdot 5 + (-5) = 15$ thỏa mãn<br>$x = 0$: $4\cdot 0 + (-5) = -5$ không thỏa mãn.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Trong các số $-5;\ 2;\ -3$, số nào là nghiệm của bất phương trình $-4x - 4 \lt 9$?', 1, N'$x = -5$: $-4\cdot (-5) + (-4) = 16$ không thỏa mãn<br>$x = 2$: $-4\cdot 2 + (-4) = -12$ thỏa mãn<br>$x = -3$: $-4\cdot (-3) + (-4) = 8$ thỏa mãn.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Trong các số $3;\ 0;\ -3$, số nào là nghiệm của bất phương trình $2x - 6 \lt -8$?', 1, N'$x = 3$: $2\cdot 3 + (-6) = 0$ không thỏa mãn<br>$x = 0$: $2\cdot 0 + (-6) = -6$ không thỏa mãn<br>$x = -3$: $2\cdot (-3) + (-6) = -12$ thỏa mãn.', 'manual', @admin);
