INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $-x - 6 \gt -6x + 3$.', 2, N'Chuyển vế: $-x + 6x \gt 3 - (-6) \Leftrightarrow 5x \gt 9$.<br>Chia hai vế cho $5$: $x \gt \frac{9}{5}$.<br>Vậy nghiệm của bất phương trình là $x \gt \frac{9}{5}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $2(x + 6) - 3 \lt x$.', 2, N'Khai triển: $2x + 9 \lt x \Leftrightarrow x \lt -9$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $-3x - 5 \le 4x - 3$.', 2, N'Chuyển vế: $-3x - 4x \le -3 - (-5) \Leftrightarrow -7x \le 2$.<br>Chia hai vế cho số âm (đổi chiều) $-7$: $x \ge -\frac{2}{7}$.<br>Vậy nghiệm của bất phương trình là $x \ge -\frac{2}{7}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $-3(x - 6) + 7 \gt 5x$.', 2, N'Khai triển: $-3x + 25 \gt 5x \Leftrightarrow -8x \gt -25$<br>$\Leftrightarrow x \lt \frac{25}{8}$ (chia cho số âm nên đổi chiều).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $2x - 3 \le -3x - 3$.', 2, N'Chuyển vế: $2x + 3x \le -3 - (-3) \Leftrightarrow 5x \le 0$.<br>Chia hai vế cho $5$: $x \le 0$.<br>Vậy nghiệm của bất phương trình là $x \le 0$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Giá cước taxi gồm $15$ nghìn đồng phí mở cửa và $12$ nghìn đồng cho mỗi km. Với $253$ nghìn đồng, có thể đi được tối đa bao nhiêu km (số nguyên)?', 3, N'Gọi $x$ là số km: $15 + 12x \le 253 \Leftrightarrow x \le \frac{119}{6}$. Số nguyên lớn nhất là $19$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$20$ km', 0), (@q, 'B', N'$19$ km', 1), (@q, 'C', N'$18$ km', 0), (@q, 'D', N'$21$ km', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Điểm trung bình môn được tính bằng (KT1 + KT2 + 2·Thi)/4. Bình được $5$ và $6$ điểm kiểm tra. Bài thi cần ít nhất bao nhiêu điểm (số nguyên) để điểm trung bình không dưới $7$?', 3, N'$\frac{5 + 6 + 2x}{4} \ge 7 \Leftrightarrow 2x \ge 17 \Leftrightarrow x \ge \frac{17}{2}$. Số nguyên nhỏ nhất: $9$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$8$ điểm', 0), (@q, 'B', N'$9$ điểm', 1), (@q, 'C', N'$10$ điểm', 0), (@q, 'D', N'$7$ điểm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Giá cước taxi gồm $10$ nghìn đồng phí mở cửa và $11$ nghìn đồng cho mỗi km. Với $107$ nghìn đồng, có thể đi được tối đa bao nhiêu km (số nguyên)?', 3, N'Gọi $x$ là số km: $10 + 11x \le 107 \Leftrightarrow x \le \frac{97}{11}$. Số nguyên lớn nhất là $8$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$8$ km', 1), (@q, 'B', N'$9$ km', 0), (@q, 'C', N'$7$ km', 0), (@q, 'D', N'$11$ km', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Điểm trung bình môn được tính bằng (KT1 + KT2 + 2·Thi)/4. Bình được $6$ và $6$ điểm kiểm tra. Bài thi cần ít nhất bao nhiêu điểm (số nguyên) để điểm trung bình không dưới $7$?', 3, N'$\frac{6 + 6 + 2x}{4} \ge 7 \Leftrightarrow 2x \ge 16 \Leftrightarrow x \ge 8$. Số nguyên nhỏ nhất: $8$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$9$ điểm', 0), (@q, 'B', N'$10$ điểm', 0), (@q, 'C', N'$8$ điểm', 1), (@q, 'D', N'$7$ điểm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Giá cước taxi gồm $12$ nghìn đồng phí mở cửa và $11$ nghìn đồng cho mỗi km. Với $203$ nghìn đồng, có thể đi được tối đa bao nhiêu km (số nguyên)?', 3, N'Gọi $x$ là số km: $12 + 11x \le 203 \Leftrightarrow x \le \frac{191}{11}$. Số nguyên lớn nhất là $17$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$18$ km', 0), (@q, 'B', N'$20$ km', 0), (@q, 'C', N'$17$ km', 1), (@q, 'D', N'$16$ km', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Điểm trung bình môn được tính bằng (KT1 + KT2 + 2·Thi)/4. Bình được $8$ và $6$ điểm kiểm tra. Bài thi cần ít nhất bao nhiêu điểm (số nguyên) để điểm trung bình không dưới $7$?', 3, N'$\frac{8 + 6 + 2x}{4} \ge 7 \Leftrightarrow 2x \ge 14 \Leftrightarrow x \ge 7$. Số nguyên nhỏ nhất: $7$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$7$ điểm', 1), (@q, 'B', N'$8$ điểm', 0), (@q, 'C', N'$6$ điểm', 0), (@q, 'D', N'$9$ điểm', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Nam có $321$ nghìn đồng và mỗi tuần để dành thêm $60$ nghìn đồng. Hỏi sau ít nhất bao nhiêu tuần Nam có không dưới $853$ nghìn đồng?', 3, N'Gọi $x$ là số tuần ($x \in \mathbb{N}$). $321 + 60x \ge 853 \Leftrightarrow x \ge \frac{133}{15}$.<br>Vậy cần ít nhất $9$ tuần.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Tìm các số nguyên $x$ thuộc đoạn $[-5; 5]$ thỏa mãn bất phương trình $2x \lt -2$.', 3, N'Giải bất phương trình: $x \lt -1$.<br>Các số nguyên thuộc $[-5; 5]$ thỏa mãn: $-5; -4; -3; -2$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Nam có $174$ nghìn đồng và mỗi tuần để dành thêm $50$ nghìn đồng. Hỏi sau ít nhất bao nhiêu tuần Nam có không dưới $1425$ nghìn đồng?', 3, N'Gọi $x$ là số tuần ($x \in \mathbb{N}$). $174 + 50x \ge 1425 \Leftrightarrow x \ge \frac{1251}{50}$.<br>Vậy cần ít nhất $26$ tuần.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Tìm các số nguyên $x$ thuộc đoạn $[-5; 5]$ thỏa mãn bất phương trình $-x + 1 \le -2$.', 3, N'Giải bất phương trình: $x \ge 3$.<br>Các số nguyên thuộc $[-5; 5]$ thỏa mãn: $3; 4; 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Nam có $342$ nghìn đồng và mỗi tuần để dành thêm $40$ nghìn đồng. Hỏi sau ít nhất bao nhiêu tuần Nam có không dưới $1130$ nghìn đồng?', 3, N'Gọi $x$ là số tuần ($x \in \mathbb{N}$). $342 + 40x \ge 1130 \Leftrightarrow x \ge \frac{197}{10}$.<br>Vậy cần ít nhất $20$ tuần.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Tìm các số nguyên $x$ thuộc đoạn $[-5; 5]$ thỏa mãn bất phương trình $-x - 4 \le -8$.', 3, N'Giải bất phương trình: $x \ge 4$.<br>Các số nguyên thuộc $[-5; 5]$ thỏa mãn: $4; 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Gói cước A: phí cố định $80$ nghìn đồng/tháng và $1$ nghìn đồng mỗi GB. Gói B: phí cố định $110$ nghìn đồng/tháng và $\frac{1}{2}$ nghìn đồng mỗi GB. Dùng bao nhiêu GB mỗi tháng (số nguyên) thì gói B rẻ hơn gói A?', 3, N'Gọi $x$ là số GB dùng mỗi tháng. Gói B rẻ hơn khi $110 + \frac{1}{2}x \lt 80 + x \Leftrightarrow \frac{1}{2}x \gt 30 \Leftrightarrow x \gt 60$.<br>Vậy dùng từ $61$ GB trở lên thì gói B rẻ hơn.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Tìm các số nguyên $x$ thuộc đoạn $[-5; 5]$ thỏa mãn bất phương trình $3x - 5 \ge -1$.', 3, N'Giải bất phương trình: $x \ge \frac{4}{3}$.<br>Các số nguyên thuộc $[-5; 5]$ thỏa mãn: $2; 3; 4; 5$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Lan có $229$ nghìn đồng, muốn mua $5$ cây bút giá $5$ nghìn đồng/cây và một số quyển vở giá $15$ nghìn đồng/quyển. Lan mua được nhiều nhất bao nhiêu quyển vở?', 3, N'Gọi $x$ là số vở. $5\cdot 5 + 15x \le 229 \Leftrightarrow 15x \le 204 \Leftrightarrow x \le \frac{68}{5}$.<br>Vậy mua được nhiều nhất $13$ quyển vở.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'mcq', N'Số nguyên nhỏ nhất thỏa mãn bất phương trình $\frac{x - 3}{3} - \frac{x + 4}{4} \gt 1$ là:', 4, N'Quy đồng mẫu $12$: $4(x - 3) - 3(x + 4) \gt 12$ $\Leftrightarrow x \gt 36$. Số nguyên nhỏ nhất là $37$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$-37$', 0), (@q, 'B', N'$36$', 0), (@q, 'C', N'$38$', 0), (@q, 'D', N'$37$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $\frac{x - 1}{4} - \frac{x - 3}{3} \ge 1$.', 4, N'Nhân hai vế với $12 \gt 0$: $3(x - 1) - 4(x - 3) \ge 12$<br>$\Leftrightarrow -x + 9 \ge 12$ $\Leftrightarrow -x \ge 3$<br>$\Leftrightarrow x \le -3$ (chia cho số âm nên đổi chiều).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Tìm $m$ để $x = 2$ là một nghiệm của bất phương trình $(m + 5)x + 4 \gt 0$.', 4, N'$x = 2$ là nghiệm khi $(m + 5)\cdot 2 + 4 \gt 0 \Leftrightarrow 2(m + 5) \gt -4$<br>$\Leftrightarrow m + 5 \gt -2$ $\Leftrightarrow m \gt -7$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Một cửa hàng nhập mỗi chiếc áo với giá $40$ nghìn đồng và bán ra $90$ nghìn đồng. Mỗi tháng cửa hàng tốn $520$ nghìn đồng chi phí cố định. Cửa hàng cần bán ít nhất bao nhiêu chiếc áo mỗi tháng để có lãi?', 4, N'Gọi $x$ là số áo bán được ($x \in \mathbb{N}$). Lãi khi $90x - 40x - 520 \gt 0 \Leftrightarrow 50x \gt 520 \Leftrightarrow x \gt \frac{52}{5}$.<br>Vậy cần bán ít nhất $11$ chiếc áo.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(7, 'essay', N'Giải bất phương trình $\frac{x - 4}{4} - \frac{x + 4}{2} \ge -3$.', 4, N'Nhân hai vế với $8 \gt 0$: $2(x - 4) - 4(x + 4) \ge -24$<br>$\Leftrightarrow -2x - 24 \ge -24$ $\Leftrightarrow -2x \ge 0$<br>$\Leftrightarrow x \le 0$ (chia cho số âm nên đổi chiều).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 24$ cm, $AC = 7$ cm, $BC = 25$ cm. Giá trị của $\sin B$ là:', 1, N'$\sin B = \frac{AC}{BC} = \frac{7}{25}$ (cạnh đối/cạnh kề/cạnh huyền so với góc $B$).', 'manual', @admin);
