INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 40$ cm, $AC = 9$ cm, $BC = 41$ cm. Giá trị của $\cot B$ là:', 1, N'$\cot B = \frac{AB}{AC} = \frac{40}{9}$ (cạnh đối/cạnh kề/cạnh huyền so với góc $B$).', 'manual', @admin);
