INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 12$ cm, $AC = 35$ cm, $BC = 37$ cm. Giá trị của $\cot B$ là:', 1, N'$\cot B = \frac{AB}{AC} = \frac{12}{35}$ (cạnh đối/cạnh kề/cạnh huyền so với góc $B$).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\frac{12}{35}$', 1), (@q, 'B', N'$\frac{35}{12}$', 0), (@q, 'C', N'$\frac{12}{37}$', 0), (@q, 'D', N'$\frac{35}{37}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 20$ cm, $AC = 21$ cm. Tính $BC$ và các tỉ số lượng giác của góc $B$.', 1, N'Theo định lí Pythagore: $BC = \sqrt{20^2 + 21^2} = \sqrt{841} = 29$ (cm).<br>$\sin B = \frac{AC}{BC} = \frac{21}{29}$; $\cos B = \frac{AB}{BC} = \frac{20}{29}$; $\tan B = \frac{AC}{AB} = \frac{21}{20}$; $\cot B = \frac{AB}{AC} = \frac{20}{21}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 35$ cm, $AC = 12$ cm. Tính $BC$ và các tỉ số lượng giác của góc $B$.', 1, N'Theo định lí Pythagore: $BC = \sqrt{35^2 + 12^2} = \sqrt{1369} = 37$ (cm).<br>$\sin B = \frac{AC}{BC} = \frac{12}{37}$; $\cos B = \frac{AB}{BC} = \frac{35}{37}$; $\tan B = \frac{AC}{AB} = \frac{12}{35}$; $\cot B = \frac{AB}{AC} = \frac{35}{12}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho tam giác $ABC$ vuông tại $A$ có $AB = 8$ cm, $AC = 6$ cm. Tính $BC$ và các tỉ số lượng giác của góc $B$.', 1, N'Theo định lí Pythagore: $BC = \sqrt{8^2 + 6^2} = \sqrt{100} = 10$ (cm).<br>$\sin B = \frac{AC}{BC} = \frac{3}{5}$; $\cos B = \frac{AB}{BC} = \frac{4}{5}$; $\tan B = \frac{AC}{AB} = \frac{3}{4}$; $\cot B = \frac{AB}{AC} = \frac{4}{3}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Tam giác $ABC$ vuông tại $A$ có $BC = 22$ cm, $\widehat{B} = 60^\circ$. Độ dài cạnh $AB$ là:', 2, N'$AB = BC\cdot \cos 60^\circ = 22\cdot \frac{1}{2} = 11$ (cm).', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$11\sqrt{3}\text{ cm}$', 0), (@q, 'B', N'$22\text{ cm}$', 0), (@q, 'C', N'$22\sqrt{3}\text{ cm}$', 0), (@q, 'D', N'$11\text{ cm}$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Cho góc nhọn $\alpha$ có $\sin\alpha = \frac{35}{37}$. Giá trị của $\cos\alpha$ là:', 2, N'$\cos^2\alpha = 1 - \sin^2\alpha = 1 - \frac{1225}{1369} = \frac{144}{1369}$, $\cos\alpha \gt 0$ nên $\cos\alpha = \frac{12}{37}$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$\frac{12}{37}$', 1), (@q, 'B', N'$\frac{37}{35}$', 0), (@q, 'C', N'$\frac{2}{37}$', 0), (@q, 'D', N'$\frac{35}{12}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Tam giác $ABC$ vuông tại $A$ có $BC = 10$ cm, $\widehat{B} = 60^\circ$. Độ dài cạnh $AB$ là:', 2, N'$AB = BC\cdot \cos 60^\circ = 10\cdot \frac{1}{2} = 5$ (cm).', 'manual', @admin);
