INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Cho góc nhọn $\alpha$ có $\sin\alpha = \frac{3}{5}$. Giá trị của $\cos\alpha$ là:', 2, N'$\cos^2\alpha = 1 - \sin^2\alpha = 1 - \frac{9}{25} = \frac{16}{25}$, $\cos\alpha \gt 0$ nên $\cos\alpha = \frac{4}{5}$.', 'manual', @admin);
