INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho góc nhọn $\alpha$ với $\sin\alpha = \frac{3}{5}$. Tính $\cos\alpha$, $\tan\alpha$ và $\cot\alpha$.', 2, N'$\cos^2\alpha = 1 - \sin^2\alpha = 1 - \frac{9}{25} = \frac{16}{25} \Rightarrow \cos\alpha = \frac{4}{5}$ (vì $\alpha$ nhọn).<br>$\tan\alpha = \frac{\sin\alpha}{\cos\alpha} = \frac{3}{4}$; $\cot\alpha = \frac{1}{\tan\alpha} = \frac{4}{3}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Giải tam giác $ABC$ vuông tại $A$, biết $BC = 24$ cm và $\widehat{B} = 30^\circ$.', 2, N'$\widehat{C} = 90^\circ - 30^\circ = 60^\circ$.<br>$AC = BC\cdot\sin B = 24\cdot \frac{1}{2} = 12$ (cm).<br>$AB = BC\cdot\cos B = 24\cdot \frac{\sqrt{3}}{2} = 12\sqrt{3}$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho góc nhọn $\alpha$ với $\sin\alpha = \frac{24}{25}$. Tính $\cos\alpha$, $\tan\alpha$ và $\cot\alpha$.', 2, N'$\cos^2\alpha = 1 - \sin^2\alpha = 1 - \frac{576}{625} = \frac{49}{625} \Rightarrow \cos\alpha = \frac{7}{25}$ (vì $\alpha$ nhọn).<br>$\tan\alpha = \frac{\sin\alpha}{\cos\alpha} = \frac{24}{7}$; $\cot\alpha = \frac{1}{\tan\alpha} = \frac{7}{24}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Giải tam giác $ABC$ vuông tại $A$, biết $BC = 4$ cm và $\widehat{B} = 30^\circ$.', 2, N'$\widehat{C} = 90^\circ - 30^\circ = 60^\circ$.<br>$AC = BC\cdot\sin B = 4\cdot \frac{1}{2} = 2$ (cm).<br>$AB = BC\cdot\cos B = 4\cdot \frac{\sqrt{3}}{2} = 2\sqrt{3}$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho góc nhọn $\alpha$ với $\sin\alpha = \frac{35}{37}$. Tính $\cos\alpha$, $\tan\alpha$ và $\cot\alpha$.', 2, N'$\cos^2\alpha = 1 - \sin^2\alpha = 1 - \frac{1225}{1369} = \frac{144}{1369} \Rightarrow \cos\alpha = \frac{12}{37}$ (vì $\alpha$ nhọn).<br>$\tan\alpha = \frac{\sin\alpha}{\cos\alpha} = \frac{35}{12}$; $\cot\alpha = \frac{1}{\tan\alpha} = \frac{12}{35}$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Một cây cao có bóng trên mặt đất dài $10$ m. Tia nắng tạo với mặt đất một góc $30^\circ$. Chiều cao của cây là:', 3, N'Chiều cao $= 10\cdot\tan 30^\circ = 10\cdot \frac{\sqrt{3}}{3} = \frac{10\sqrt{3}}{3}$ (m).', 'manual', @admin);
