INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Một chiếc thang dài $4$ m dựa vào tường, chân thang tạo với mặt đất một góc $60^\circ$. Đỉnh thang cách mặt đất bao nhiêu mét?', 3, N'Độ cao $= 4\cdot\sin 60^\circ = 4\cdot \frac{\sqrt{3}}{2} = 2\sqrt{3}$ (m).', 'manual', @admin);
