INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Một chiếc thang dài $12$ m dựa vào tường, chân thang tạo với mặt đất một góc $30^\circ$. Đỉnh thang cách mặt đất bao nhiêu mét?', 3, N'Độ cao $= 12\cdot\sin 30^\circ = 12\cdot \frac{1}{2} = 6$ (m).', 'manual', @admin);
