INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một tòa nhà có bóng trên mặt đất dài $17$ m khi tia nắng mặt trời tạo với mặt đất một góc $45^\circ$. Tính chiều cao tòa nhà (làm tròn đến hàng phần mười).', 3, N'Gọi $h$ là chiều cao tòa nhà. Trong tam giác vuông tạo bởi tòa nhà, bóng và tia nắng: $\tan 45^\circ = \frac{h}{17}$.<br>$h = 17\cdot\tan 45^\circ = 17$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một con dốc dài $17$ m nghiêng với mặt đất một góc $60^\circ$. Tính độ cao của đỉnh dốc so với mặt đất và khoảng cách theo phương ngang từ chân dốc đến điểm ngay dưới đỉnh dốc (làm tròn đến hàng phần mười).', 3, N'Độ cao $h = 17\cdot\sin 60^\circ = 17\cdot \frac{\sqrt{3}}{2} \approx 14{,}7$ (m).<br>Khoảng cách ngang $d = 17\cdot\cos 60^\circ = 17\cdot \frac{1}{2} \approx 8{,}5$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một cột cờ cao $5$ m có bóng trên mặt đất dài $12$ m. Tính $\tan$ của góc tạo bởi tia nắng với mặt đất và khoảng cách từ đỉnh cột cờ đến đầu mút của bóng.', 3, N'Gọi $\alpha$ là góc tạo bởi tia nắng và mặt đất: $\tan\alpha = \frac{5}{12}$.<br>Khoảng cách từ đỉnh cột đến đầu bóng: $\sqrt{5^2 + 12^2} = \sqrt{169} = 13$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một tòa nhà có bóng trên mặt đất dài $3$ m khi tia nắng mặt trời tạo với mặt đất một góc $60^\circ$. Tính chiều cao tòa nhà (làm tròn đến hàng phần mười).', 3, N'Gọi $h$ là chiều cao tòa nhà. Trong tam giác vuông tạo bởi tòa nhà, bóng và tia nắng: $\tan 60^\circ = \frac{h}{3}$.<br>$h = 3\cdot\tan 60^\circ = 3\sqrt{3} \approx 5{,}2$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một con dốc dài $9$ m nghiêng với mặt đất một góc $30^\circ$. Tính độ cao của đỉnh dốc so với mặt đất và khoảng cách theo phương ngang từ chân dốc đến điểm ngay dưới đỉnh dốc (làm tròn đến hàng phần mười).', 3, N'Độ cao $h = 9\cdot\sin 30^\circ = 9\cdot \frac{1}{2} \approx 4{,}5$ (m).<br>Khoảng cách ngang $d = 9\cdot\cos 30^\circ = 9\cdot \frac{\sqrt{3}}{2} \approx 7{,}8$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một cột cờ cao $45$ m có bóng trên mặt đất dài $24$ m. Tính $\tan$ của góc tạo bởi tia nắng với mặt đất và khoảng cách từ đỉnh cột cờ đến đầu mút của bóng.', 3, N'Gọi $\alpha$ là góc tạo bởi tia nắng và mặt đất: $\tan\alpha = \frac{15}{8}$.<br>Khoảng cách từ đỉnh cột đến đầu bóng: $\sqrt{45^2 + 24^2} = \sqrt{2601} = 51$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một tòa nhà có bóng trên mặt đất dài $19$ m khi tia nắng mặt trời tạo với mặt đất một góc $45^\circ$. Tính chiều cao tòa nhà (làm tròn đến hàng phần mười).', 3, N'Gọi $h$ là chiều cao tòa nhà. Trong tam giác vuông tạo bởi tòa nhà, bóng và tia nắng: $\tan 45^\circ = \frac{h}{19}$.<br>$h = 19\cdot\tan 45^\circ = 19$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một con dốc dài $11$ m nghiêng với mặt đất một góc $60^\circ$. Tính độ cao của đỉnh dốc so với mặt đất và khoảng cách theo phương ngang từ chân dốc đến điểm ngay dưới đỉnh dốc (làm tròn đến hàng phần mười).', 3, N'Độ cao $h = 11\cdot\sin 60^\circ = 11\cdot \frac{\sqrt{3}}{2} \approx 9{,}5$ (m).<br>Khoảng cách ngang $d = 11\cdot\cos 60^\circ = 11\cdot \frac{1}{2} \approx 5{,}5$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Một cột cờ cao $6$ m có bóng trên mặt đất dài $8$ m. Tính $\tan$ của góc tạo bởi tia nắng với mặt đất và khoảng cách từ đỉnh cột cờ đến đầu mút của bóng.', 3, N'Gọi $\alpha$ là góc tạo bởi tia nắng và mặt đất: $\tan\alpha = \frac{3}{4}$.<br>Khoảng cách từ đỉnh cột đến đầu bóng: $\sqrt{6^2 + 8^2} = \sqrt{100} = 10$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'mcq', N'Giá trị của biểu thức $\sin^2 28^\circ + \sin^2 62^\circ + 2\tan 42^\circ\cdot\tan 48^\circ$ là:', 4, N'$\sin 62^\circ = \cos 28^\circ$ nên $\sin^2 28^\circ + \cos^2 28^\circ = 1$; $\tan 48^\circ = \cot 42^\circ$ nên $\tan 42^\circ\cdot\cot 42^\circ = 1$. Kết quả: $1 + 2 = 3$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$2$', 0), (@q, 'B', N'$1$', 0), (@q, 'C', N'$4$', 0), (@q, 'D', N'$3$', 1);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Từ điểm $A$ trên mặt đất, một người nhìn đỉnh tháp với góc nâng $30^\circ$. Đi thêm $40$ m về phía tháp đến điểm $B$ thì góc nâng là $60^\circ$. Tính chiều cao của tháp (làm tròn đến hàng phần mười).', 4, N'Gọi $h$ là chiều cao tháp, $H$ là chân tháp. Khi đó $AH = h\cot 30^\circ = h\sqrt{3}$, $BH = h\cot 60^\circ = \frac{h}{\sqrt{3}}$.<br>$AB = AH - BH = h\sqrt{3} - \frac{h}{\sqrt{3}} = \frac{2h}{\sqrt{3}} = 40 \Rightarrow h = 20\sqrt{3} \approx 34{,}6$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Không dùng máy tính, tính giá trị của biểu thức $P = \frac{\sin 57^\circ}{\cos 33^\circ} + \tan 57^\circ\cdot\tan 33^\circ - \sin^2 57^\circ - \sin^2 33^\circ$.', 4, N'Vì $57^\circ + 33^\circ = 90^\circ$ nên $\cos 33^\circ = \sin 57^\circ$, $\tan 33^\circ = \cot 57^\circ$, $\sin 33^\circ = \cos 57^\circ$.<br>$P = 1 + \tan 57^\circ\cdot\cot 57^\circ - (\sin^2 57^\circ + \cos^2 57^\circ) = 1 + 1 - 1 = 1$.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Cho tam giác $ABC$ vuông tại $A$, đường cao $AH$, có $AB = 24$ cm, $AC = 7$ cm. Tính $BC$, $AH$, $\sin B$ và $BH$.', 4, N'$BC = \sqrt{24^2 + 7^2} = 25$ (cm).<br>$AH = \frac{AB\cdot AC}{BC} = \frac{24\cdot 7}{25} = \frac{168}{25}$ (cm).<br>$\sin B = \frac{AC}{BC} = \frac{7}{25}$.<br>$BH = AB\cdot\cos B = 24\cdot \frac{24}{25} = \frac{576}{25}$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(8, 'essay', N'Từ điểm $A$ trên mặt đất, một người nhìn đỉnh tháp với góc nâng $30^\circ$. Đi thêm $54$ m về phía tháp đến điểm $B$ thì góc nâng là $60^\circ$. Tính chiều cao của tháp (làm tròn đến hàng phần mười).', 4, N'Gọi $h$ là chiều cao tháp, $H$ là chân tháp. Khi đó $AH = h\cot 30^\circ = h\sqrt{3}$, $BH = h\cot 60^\circ = \frac{h}{\sqrt{3}}$.<br>$AB = AH - BH = h\sqrt{3} - \frac{h}{\sqrt{3}} = \frac{2h}{\sqrt{3}} = 54 \Rightarrow h = 27\sqrt{3} \approx 46{,}8$ (m).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Trong đường tròn bán kính $5$ cm, dây cung dài nhất có độ dài là:', 1, N'Đường kính là dây lớn nhất, dài $2R = 10$ cm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$10\text{ cm}$', 1), (@q, 'B', N'$25\text{ cm}$', 0), (@q, 'C', N'$5\sqrt{2}\text{ cm}$', 0), (@q, 'D', N'$5\text{ cm}$', 0);
