INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 3\text{ cm})$ và ba điểm $A, B, C$ với $OA = 1$ cm, $OB = 3$ cm, $OC = 4$ cm. Xác định vị trí của mỗi điểm đối với đường tròn.', 1, N'$A$: $OA = 1$ $\lt R$ nên nằm trong đường tròn<br>$B$: $OB = 3$ $= R$ nên nằm trên đường tròn<br>$C$: $OC = 4$ $\gt R$ nên nằm ngoài đường tròn.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 10\text{ cm})$ và ba điểm $A, B, C$ với $OA = 10$ cm, $OB = 1$ cm, $OC = 16$ cm. Xác định vị trí của mỗi điểm đối với đường tròn.', 1, N'$A$: $OA = 10$ $= R$ nên nằm trên đường tròn<br>$B$: $OB = 1$ $\lt R$ nên nằm trong đường tròn<br>$C$: $OC = 16$ $\gt R$ nên nằm ngoài đường tròn.', 'manual', @admin);
