INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Đường tròn $(O; 17\text{ cm})$ có dây $AB = 30$ cm. Khoảng cách từ $O$ đến dây $AB$ là:', 2, N'Gọi $H$ là trung điểm $AB$ thì $OH \perp AB$, $AH = 15$. $OH = \sqrt{17^2 - 15^2} = \sqrt{64} = 8$ (cm).', 'manual', @admin);
