INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 25\text{ cm})$ và dây $AB = 14$ cm. Tính khoảng cách từ tâm $O$ đến dây $AB$.', 2, N'Kẻ $OH \perp AB$ tại $H$ thì $H$ là trung điểm của $AB$ (đường kính vuông góc với dây), $AH = 7$ cm.<br>Tam giác $OAH$ vuông tại $H$: $OH = \sqrt{OA^2 - AH^2} = \sqrt{25^2 - 7^2} = 24$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Dây $CD$ của đường tròn $(O; 41\text{ cm})$ cách tâm $9$ cm. Tính độ dài dây $CD$.', 2, N'Kẻ $OK \perp CD$ tại $K$ thì $K$ là trung điểm của $CD$ và $OK = 9$.<br>$CK = \sqrt{OC^2 - OK^2} = \sqrt{41^2 - 9^2} = 40$ (cm). Vậy $CD = 2CK = 80$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 37\text{ cm})$ và dây $AB = 70$ cm. Tính khoảng cách từ tâm $O$ đến dây $AB$.', 2, N'Kẻ $OH \perp AB$ tại $H$ thì $H$ là trung điểm của $AB$ (đường kính vuông góc với dây), $AH = 35$ cm.<br>Tam giác $OAH$ vuông tại $H$: $OH = \sqrt{OA^2 - AH^2} = \sqrt{37^2 - 35^2} = 12$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Dây $CD$ của đường tròn $(O; 34\text{ cm})$ cách tâm $30$ cm. Tính độ dài dây $CD$.', 2, N'Kẻ $OK \perp CD$ tại $K$ thì $K$ là trung điểm của $CD$ và $OK = 30$.<br>$CK = \sqrt{OC^2 - OK^2} = \sqrt{34^2 - 30^2} = 16$ (cm). Vậy $CD = 2CK = 32$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 26\text{ cm})$ và dây $AB = 48$ cm. Tính khoảng cách từ tâm $O$ đến dây $AB$.', 2, N'Kẻ $OH \perp AB$ tại $H$ thì $H$ là trung điểm của $AB$ (đường kính vuông góc với dây), $AH = 24$ cm.<br>Tam giác $OAH$ vuông tại $H$: $OH = \sqrt{OA^2 - AH^2} = \sqrt{26^2 - 24^2} = 10$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Đường tròn $(O; 17\text{ cm})$ có hai dây song song $AB = 30$ cm và $CD = 16$ cm nằm cùng phía đối với tâm $O$. Khoảng cách giữa hai dây là:', 3, N'Khoảng cách từ $O$ đến $AB$: $\sqrt{17^2 - 15^2} = 8$; đến $CD$: $\sqrt{17^2 - 8^2} = 15$. Cùng phía nên khoảng cách là $|8 - 15| = 7$ cm.', 'manual', @admin);
