INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Đường tròn $(O; 26\text{ cm})$ có hai dây song song $AB = 20$ cm và $CD = 48$ cm nằm cùng phía đối với tâm $O$. Khoảng cách giữa hai dây là:', 3, N'Khoảng cách từ $O$ đến $AB$: $\sqrt{26^2 - 10^2} = 24$; đến $CD$: $\sqrt{26^2 - 24^2} = 10$. Cùng phía nên khoảng cách là $|24 - 10| = 14$ cm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$52\text{ cm}$', 0), (@q, 'B', N'$15\text{ cm}$', 0), (@q, 'C', N'$14\text{ cm}$', 1), (@q, 'D', N'$34\text{ cm}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Cho đường tròn $(O; 13\text{ cm})$ và điểm $M$ với $OM = 5$ cm. Dây ngắn nhất đi qua $M$ có độ dài là:', 3, N'Dây ngắn nhất qua $M$ là dây vuông góc với $OM$ tại $M$; nửa dây bằng $\sqrt{13^2 - 5^2} = 12$, nên dây dài $24$ cm.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$26\text{ cm}$', 0), (@q, 'B', N'$24\text{ cm}$', 1), (@q, 'C', N'$12\text{ cm}$', 0), (@q, 'D', N'$10\text{ cm}$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 25\text{ cm})$ và hai dây song song $AB = 14$ cm, $CD = 48$ cm. Tính khoảng cách giữa hai dây trong hai trường hợp: hai dây cùng phía và khác phía đối với tâm $O$.', 3, N'Kẻ đường thẳng qua $O$ vuông góc với hai dây, cắt $AB$ tại $H$, $CD$ tại $K$ ($H, K$ là trung điểm của hai dây).<br>$OH = \sqrt{25^2 - 7^2} = 24$ cm; $OK = \sqrt{25^2 - 24^2} = 7$ cm.<br>- Cùng phía: $HK = |OH - OK| = 17$ cm.<br>- Khác phía: $HK = OH + OK = 31$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 25\text{ cm})$, dây $AB$ có trung điểm $M$ với $OM = 24$ cm. Tính độ dài dây $AB$ và chu vi tam giác $OAB$.', 3, N'$M$ là trung điểm dây $AB$ (không qua tâm) nên $OM \perp AB$.<br>$AM = \sqrt{OA^2 - OM^2} = \sqrt{25^2 - 24^2} = 7$ cm $\Rightarrow AB = 14$ cm.<br>Chu vi tam giác $OAB$: $OA + OB + AB = 25 + 25 + 14 = 64$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 41\text{ cm})$ và dây $AB = 80$ cm. Tính diện tích tam giác $OAB$.', 3, N'Kẻ $OH \perp AB$ thì $H$ là trung điểm $AB$, $AH = 40$ cm, $OH = \sqrt{41^2 - 40^2} = 9$ cm.<br>$S_{OAB} = \frac{1}{2}\cdot AB\cdot OH = \frac{1}{2}\cdot 80\cdot 9 = 360$ (cm$^2$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 41\text{ cm})$ và hai dây song song $AB = 18$ cm, $CD = 80$ cm. Tính khoảng cách giữa hai dây trong hai trường hợp: hai dây cùng phía và khác phía đối với tâm $O$.', 3, N'Kẻ đường thẳng qua $O$ vuông góc với hai dây, cắt $AB$ tại $H$, $CD$ tại $K$ ($H, K$ là trung điểm của hai dây).<br>$OH = \sqrt{41^2 - 9^2} = 40$ cm; $OK = \sqrt{41^2 - 40^2} = 9$ cm.<br>- Cùng phía: $HK = |OH - OK| = 31$ cm.<br>- Khác phía: $HK = OH + OK = 49$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 37\text{ cm})$, dây $AB$ có trung điểm $M$ với $OM = 12$ cm. Tính độ dài dây $AB$ và chu vi tam giác $OAB$.', 3, N'$M$ là trung điểm dây $AB$ (không qua tâm) nên $OM \perp AB$.<br>$AM = \sqrt{OA^2 - OM^2} = \sqrt{37^2 - 12^2} = 35$ cm $\Rightarrow AB = 70$ cm.<br>Chu vi tam giác $OAB$: $OA + OB + AB = 37 + 37 + 70 = 144$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 26\text{ cm})$ và dây $AB = 48$ cm. Tính diện tích tam giác $OAB$.', 3, N'Kẻ $OH \perp AB$ thì $H$ là trung điểm $AB$, $AH = 24$ cm, $OH = \sqrt{26^2 - 24^2} = 10$ cm.<br>$S_{OAB} = \frac{1}{2}\cdot AB\cdot OH = \frac{1}{2}\cdot 48\cdot 10 = 240$ (cm$^2$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 13\text{ cm})$ và hai dây song song $AB = 10$ cm, $CD = 24$ cm. Tính khoảng cách giữa hai dây trong hai trường hợp: hai dây cùng phía và khác phía đối với tâm $O$.', 3, N'Kẻ đường thẳng qua $O$ vuông góc với hai dây, cắt $AB$ tại $H$, $CD$ tại $K$ ($H, K$ là trung điểm của hai dây).<br>$OH = \sqrt{13^2 - 5^2} = 12$ cm; $OK = \sqrt{13^2 - 12^2} = 5$ cm.<br>- Cùng phía: $HK = |OH - OK| = 7$ cm.<br>- Khác phía: $HK = OH + OK = 17$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 10\text{ cm})$, dây $AB$ có trung điểm $M$ với $OM = 8$ cm. Tính độ dài dây $AB$ và chu vi tam giác $OAB$.', 3, N'$M$ là trung điểm dây $AB$ (không qua tâm) nên $OM \perp AB$.<br>$AM = \sqrt{OA^2 - OM^2} = \sqrt{10^2 - 8^2} = 6$ cm $\Rightarrow AB = 12$ cm.<br>Chu vi tam giác $OAB$: $OA + OB + AB = 10 + 10 + 12 = 32$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 29\text{ cm})$ và dây $AB = 42$ cm. Tính diện tích tam giác $OAB$.', 3, N'Kẻ $OH \perp AB$ thì $H$ là trung điểm $AB$, $AH = 21$ cm, $OH = \sqrt{29^2 - 21^2} = 20$ cm.<br>$S_{OAB} = \frac{1}{2}\cdot AB\cdot OH = \frac{1}{2}\cdot 42\cdot 20 = 420$ (cm$^2$).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'mcq', N'Cho đường tròn $(O; 25\text{ cm})$ và điểm $M$ nằm trong đường tròn với $OM = 24$ cm. Có bao nhiêu dây đi qua $M$ có độ dài là số nguyên (cm)?', 4, N'Dây qua $M$ dài nhất là đường kính $50$ cm (1 dây), ngắn nhất là dây vuông góc với $OM$ dài $2\sqrt{25^2 - 24^2} = 14$ cm (1 dây). Mỗi độ dài nguyên $l$ với $14 \lt l \lt 50$ ứng với đúng 2 dây (đối xứng qua $OM$). Số dây: $1 + 1 + 2\cdot 35 = 72$.', 'manual', @admin);
INSERT INTO QuestionOptions(QuestionId, OptionLabel, Content, IsCorrect) VALUES (@q, 'A', N'$72$', 1), (@q, 'B', N'$50$', 0), (@q, 'C', N'$37$', 0), (@q, 'D', N'$74$', 0);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 26\text{ cm})$ và điểm $M$ với $OM = 24$ cm. Tính độ dài dây dài nhất và dây ngắn nhất đi qua $M$. Giải thích.', 4, N'- Dây dài nhất qua $M$ là đường kính đi qua $M$: dài $2R = 52$ cm.<br>- Gọi $AB$ là dây bất kì qua $M$, $H$ là trung điểm $AB$ thì $OH \le OM$. Dây càng xa tâm càng ngắn nên $AB$ ngắn nhất khi $OH = OM$, tức $AB \perp OM$ tại $M$.<br>Khi đó $AM = \sqrt{26^2 - 24^2} = 10$ cm, dây ngắn nhất dài $20$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 25\text{ cm})$ có hai dây song song $AB = 14$ cm và $CD = 30$ cm. Tính khoảng cách giữa hai dây (xét hai trường hợp).', 4, N'Khoảng cách từ $O$ đến $AB$: $\sqrt{25^2 - 7^2} = 24$ cm; đến $CD$: $\sqrt{25^2 - 15^2} = 20$ cm.<br>- Hai dây cùng phía đối với $O$: khoảng cách $= |24 - 20| = 4$ cm.<br>- Khác phía: khoảng cách $= 24 + 20 = 44$ cm.', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 17\text{ cm})$, dây $AB = 16$ cm. Tính khoảng cách từ $O$ đến $AB$, rồi tính độ dài đường cao kẻ từ $A$ của tam giác $OAB$.', 4, N'$OH = \sqrt{17^2 - 8^2} = 15$ cm ($H$ là trung điểm $AB$). $S_{OAB} = \frac{1}{2}\cdot 16\cdot 15 = 120$ cm$^2$.<br>Đường cao từ $A$ xuống $OB$: $h = \frac{2S}{OB} = \frac{240}{17}$ (cm).', 'manual', @admin);
INSERT INTO Questions(TopicId, QuestionType, Content, Level, Solution, Source, CreatedBy) VALUES(9, 'essay', N'Cho đường tròn $(O; 37\text{ cm})$ và điểm $M$ với $OM = 35$ cm. Tính độ dài dây dài nhất và dây ngắn nhất đi qua $M$. Giải thích.', 4, N'- Dây dài nhất qua $M$ là đường kính đi qua $M$: dài $2R = 74$ cm.<br>- Gọi $AB$ là dây bất kì qua $M$, $H$ là trung điểm $AB$ thì $OH \le OM$. Dây càng xa tâm càng ngắn nên $AB$ ngắn nhất khi $OH = OM$, tức $AB \perp OM$ tại $M$.<br>Khi đó $AM = \sqrt{37^2 - 35^2} = 12$ cm, dây ngắn nhất dài $24$ cm.', 'manual', @admin);
